window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_016"]={"n":"钱澄之","dyn":"清","poems":[{"t":"马上看月","f":"七言绝句","c":["露白烟消欲夜天，冰轮却向马头圆。","此时见月唯行客，一路人家尽早眠。"]},{"t":"和方有怀孤鸳鸯诗","f":"七言绝句","c":["十首诗成尽可怜，怜他只影小窗前。","也知岭外归来客，独宿松间十七年。"]},{"t":"和方有怀孤鸳鸯诗","f":"七言绝句","c":["此生交颈梦难成，愧煞人间伉俪情。","唤作鸳鸯单不得，时时顾影怕呼名。"]},{"t":"水村即事示诸从子","f":"五言律诗","c":["近水山都小，穿湖路尽通。","帆低归浦雨，伞敌到家风。","门绣苍苔涩，堤号老树空。","全家生活计，都在淼茫中。"]},{"t":"伤心诗 其三","f":"七言律诗","c":["三十年来底事忙，梳头一半已成霜。","宵寒被裂山僧绽，病卧药香小竖尝。","羡尔渔樵能挈耦，看人儿女喜还乡。","飘零莫忆家园事，记得团栾夜绕床！"]},{"t":"伤心诗 其二","f":"七言律诗","c":["著眼空华一刻徂，苍天何意夺童乌。","玉台已碎怀中镜，明月还沈掌上珠！","早信灵氛逃大劫，难将因果问浮屠。","平生儿女钟情甚，此际黄泉舐犊无？"]},{"t":"伤心诗 其一","f":"七言律诗","c":["屈指吴江死别时，孤情此日已全痴。","子山漫著伤心赋，孙楚休传除服诗！","海外无香回玉树，帐中何术召蛾眉！","故园小阁经年锁，花落花开见阿谁！"]},{"t":"江村杂述","f":"五言律诗","c":["自来生计少，难后更何营？","襆被让寒女，稻粱分老兄。","儿知盐米贵，天与利名轻。","得饱殊非易，明年我欲耕。"]},{"t":"江村杂述","f":"五言律诗","c":["老屋江皋近，兵船上下愁。","只求连夜过，怕被斗风留。","烽火沿村放，鸡豚比户搜。","芦中多难妇，莫劝土人收。"]},{"t":"还家杂感","f":"七言律诗","c":["此生谁料有还期，哭罢相看梦里疑。","同产仅余三子在，一门犹仗两兄持。","箧中泪渍游人信，壁上蜗残忆弟诗。","不是天涯归意懒，归懒原怕到家时。"]},{"t":"还家杂感","f":"七言律诗","c":["近家才听丧吾兄，望见柴门百感并。","得病只闻思弟剧，远归虚拟出村迎。","哭爷娇女帷前识，绕膝孤儿别后生。","素喜拮据遗迹遍，经行何处不伤情。"]},{"t":"金陵即事","f":"七言律诗","c":["城郭人民迥未移，夕阳鼓角不胜悲。","屋檐几处添宫瓦，石路何年践御碑。","祠废已无官树禁，寺荒端为赐田追。","酒楼遍唱关东调，谁听秦淮旧竹枝？"]},{"t":"金陵即事","f":"七言律诗","c":["秋山无树故崚嶒，几度支筇未忍登。","荒路行愁逢牧马，旧交老渐变高僧。","钟楼自吼南朝寺，佛塔还燃半夜灯。","莫向雨花台北望，寒云黯淡是钟陵。"]},{"t":"梅花 其一","f":"五言律诗","c":["何处花先放，向南三两村。","未春天似梦，彻夜月无言。","且喜昏鸦散，毋嫌翠羽喧。","众芳久寂寞，赖汝照乾坤。"]},{"t":"梅花 其二","f":"五言律诗","c":["离离压残雪，脉脉照溪滨。","一任夜无月，何妨天不春。","芳华凭俗赏，风味与谁亲。","祇觉闭门后，徘徊似有人。"]},{"t":"遇曾庭闻芜阴市上","f":"七言律诗","c":["自着淄衣万恨平，穷途遇尔转伤情。","我从岭外经年至，君向江南何处行？","瓢笠喜无乡里识，须眉犹使故人惊。","相持莫便当街哭，为到郊原一放声。"]},{"t":"水夫谣","f":"七言古诗","c":["水夫住在长江边，年年捉送装兵船。","上水下水不计数，但见船来点夫去。","十家门派一夫行，生死向前无怨声。","衣中何有苦搜索，身无钱使夜当缚。","遭他鞭挞无完肤，行迟还用刀箭驱。","掣刀在腰箭在手，人命贱同豕与狗。","射死纷纷满路尸，那敢问人死者谁？","爷娘养汝才得力，送汝出门倚门泣。","腐肉已充乌鸢饥，家家犹望水夫归。"]},{"t":"田园杂诗 其一","f":"五言古诗","c":["仲春遘时雨，既雨旋亦晴。","百草吐生意，众鸟喧新声。","纷纷群动出，各各有其营。","孰是形骸具，而怀安居情。","秉耒赴田皋，叱牛出柴荆。","耒耜非素习，用力多不精。","老农悯我拙，解轭为我耕。","教以驾驭法，使我牛肯行。","置酒谢老农，愿言俟秋成。"]},{"t":"田园杂诗 其二","f":"五言古诗","c":["今晨放大牛，水田调生犊。","稚子原上呼，有客访茅屋。","田乌噪正喧，招手去何速。","念此为谁欤，有马又有仆。","舍耕还入门，友谊素云笃。","田潦湿我衣，泥涂沾我足，且为解袯襫，易我揖让服。","故人持不听，讶我未免俗。","呼儿出草堂，敕厨炊脱粟。","我去送牛来，今夜留客宿。"]},{"t":"田园杂诗 其三","f":"五言古诗","c":["驾牛东皋上，有客问我经。","我牛依田转，客亦随我行。","请问大《易》旨，此理不易听。","乾卦冠潜龙，遁世去其名。","奇门称遁甲，乃能役九星。","祇兹无首义，可农亦可兵。","八卦周天转，六位以时成。","时哉不可背，亦岂容将迎。","朝为辇上客，夕为陇上耕。","斯义如转圜，指出子应聆。","顾客且安坐，吾牛不肯停。","东园有嘉树，开花照昏晓。","一为葛藟萦，遂使枝条槁。","枝条既以尽，葛藟萦未了。","我欲解其缠，轇轕死相抱。","念此不能除，斩断乃为好。","斩藤树亦伤，藤去树以保。","今晨心目旷，宿秽净如扫。","乐哉嘉树柯，且复惜其老。","寄言种树人，此物去宜早。"]},{"t":"田园杂诗 其四","f":"五言古诗","c":["屋上春鸠鸣，田家谷始播。","时雨催我还，倚锸檐前坐。","牧童去未归，雨声听渐大。","时雨岂不嘉，所虑老牛饿。","自往唤牧童，牵牛入兰卧。","我牛既以来，我锸行须荷。","田畴及时治，况复雨初过。","亦知冒雨寒，为农焉敢惰。"]},{"t":"田园杂诗 其五","f":"五言古诗","c":["春天不久晴，衣垢及时浣。","身上何所著，敝襦及骭短。","家人念我寒，一杯为斟满。","酒满不可多，农事不可缓。","奋身田野间，襟带忽以散。","乃知四体勤，无衣亦自暖。","君看狐貉温，转使腰肢懒。"]},{"t":"田园杂诗 其六","f":"五言古诗","c":["人生会有尽，行止非自由。","止亦不可趣，行亦不可留。","如何柴桑叟，汲汲为此忧。","终年痛饮酒，冀以忘其愁。","吾身听物化，化及事则休。","当其未化时，焉能弃所谋。","有子亦须教，有田亦望收。","天心与人事，何息不周流。","我不离世间，而愿与天游。","焉能外亲戚，视之同聚沤。","乃知黄老书，不如孔与周。"]},{"t":"鸡鸣","f":"七言古诗","c":["冬已过半夜偏长，愁人不眠独在床。","寒鸡拥翰不肯叫，老鸱得气山头啸。","山头有虎伺人行，伥鬼骑虎学鸡鸣。","鸡在墙根鼓两翅，欲鸣不鸣时未至。","村南村北闻犬喧，鸡未三唱勿出门。","窗前山鬼太无赖，低头树下学人拜。","遥遥古寺打钟声，一声一拜声声惊。","鸡鸣一声天下白，千状万态从此灭。"]},{"t":"湖孰种菜歌","f":"七言古诗","c":["金陵城东湖孰村，中有隐者开平孙。","通侯甲第今已矣，意气豪华无复存。","开平去今凡几代，五王之后惟君在。","往昔争言青门瓜，如今独数湖孰菜。","问谁种菜满畦新，一家生计只三人。","终岁把锄菜畦里，妇能炊饭儿负薪。","为君妇亦太辛苦，娇贵当年难比数。","翟珈赐出小侯妻，珠翠里成上公女。","都人犹记嫁时装，如云妾媵烂生光。","台前照镜轮梳髻，架上熏衣派管香。","一朝散去竟何有，相对惟余双白首。","早从府内厌笙歌，还向村中操井臼。","村中井臼倚柴扉，卖菜还愁终岁饥。","衣长不肯燃薪坐，十指侵寒绽故衣。","东川子孙公主裔，妻孥行汲心常愧。","闻说君妇尽伤情，无心更拟求奴婢。"]},{"t":"叶声","f":"五言律诗","c":["坠响空阶静，辞柯一叶乾。","无风吹地走，不雨打帘寒。","已觉扫堪惜，还怜踏欲残。","掩门深坐听，山路正漫漫。"]},{"t":"月夜过沈氏江楼","f":"五言律诗","c":["何处堪乘月，沈家楼最明。","晚来江更大，秋到水初清。","远火移时隐，孤舟犯夜行。","市门催客去，早是起更声。"]},{"t":"别孙不害途中有怀","f":"五言律诗","c":["出街别孙楚，驴背独成眠。","客影瘦残照，人声喧渡船。","鱼罾争闸口，牛路指墟烟。","念尔柴关掩，初抄《秒水》篇。"]},{"t":"暑中走椒岭省方氏姊示诸甥","f":"七言律诗","c":["十七年前椒岭路，短驴疑在梦中行。","兵烽几度门无径，灵雨初通涧有声。","牛屋半楹啼寡姊，蔬盘一夜费贫甥。","老来万事心灰尽，益重人间骨肉情。"]},{"t":"鸠兹酬张惕中","f":"七言律诗","c":["江头破衲少知名，脱粟亲炊见尔情。","痛入箭创阴雨夜，梦回鼙鼓海潮声。","国恩祇觉今生重，交道谁言乱世轻。","传说敬亭曾卧病，又冲泥泞去宣城。"]},{"t":"庐山","f":"七言律诗","c":["匡庐入梦已多时，乘兴先探绝顶奇。","一路叶埋灵运屐，合山僧待子瞻诗。","云铺半岭村犹霁，雨在高峰客不知。","小竖暗携长笛至，拟登五老向空吹。"]},{"t":"假亲王","f":"五言古诗","c":["狂贼昔猖獗，诸藩皆炭涂。","幸免有几人，亡命窜天隅！","如何妄男子，乃有非分图。","诏狱酷锻鍊，一死伏其辜！","或云福世子，国破民间逋。","南都新立帝，匍匐趋乘舆。","徼幸思袭国，冒昧还遭诛！","不闻隽不疑，叱收黄犊车？","满朝尽通经，世子来何愚！"]},{"t":"假后","f":"五言古诗","c":["福国昔破散，骨肉如飘蓬。","诸王更衣遁，妃主不得从。","如何妄妇人，御史扈还宫！","叩阍不见容，榜掠词已穷。","愿归掖庭死，得一识重瞳！","或云世子妇，流落里妇同。","闻王即帝位，自谓匹圣躬。","庶几邢夫人，御环得相逢。","不知今上谁，空死囹圄中！"]},{"t":"假太子","f":"五言古诗","c":["昔闻燕京亡，诸王已陷贼。","挟之左右随，贼去无消息。","如何妄小儿，憔悴来河北。","云是旧东宫，脱身今返国！","宫监无敢认，讲官不相识。","后云王之明，拷讯已吐实。","党人为主使，大狱事罗织！","国亡天子走，群小拥登极。","与上同被擒，并侍贤王侧。","贤王偕北还，真伪竟谁测！"]},{"t":"二忠诗 其一 史相国可法","f":"七言律诗","c":["史公将略本非长，半壁南朝一死偿！","庭议祗知除异己，庙谋宁复顾危疆。","上江斗罢扬州破，北府屯空建业亡。","二竖至今还兔脱，槛车独见送君王。"]},{"t":"二忠诗 其二 靖南侯黄得功","f":"七言律诗","c":["靖南勇气冠诸勋，报主精忠独数君！","鹰饱祗教防兔窟，虎痴何意入狐群！","上流问罪偏劳拒，北道求援未许闻。","国运可怜亡一矢，江城遗恨失将军！"]},{"t":"哀越诗 其一","f":"七言律诗","c":["总戎使节驻南湖，更会军容万舳舻。","共拟返旗枭二竖，即看传檄号三吴。","江城有险应先据，越国行成且缓图。","底事金缯饱搜索，望尘舞蹈作前驱！"]},{"t":"哀越诗 其二","f":"七言律诗","c":["金陵王气已应终，马相旌麾向越中。","北狩君王空有恨，南来太后且论功。","孔苌建议诛夷甫，玄礼何雠戮国忠！","底事杭州三学士，不闻请剑有陈东！"]},{"t":"悲愤诗","f":"五言古诗","c":["南渡失国柄，二竖覆皇都。","武昌兴甲兵，传檄诛奸徒。","烽火照河北，四镇还相图。","撤兵防上游，坐视扬州屠。","所虑楚师下，宁忧胡马驱！","胡马渡江来，奸臣弃主逋。","可怜佳丽地，士女成炭涂！","我友报韩切，义旗倡三吴。","磨盾草檄文，鬼神泣通衢。","一战不得当，诸将人人殊。","书生愤所激，攘臂愿执殳。","兵力虽不敌，志已无完躯。","遇难震泽滨，事败志勿渝。","我友赴深渊，我生聊须臾。","宛转娇儿女，枕藉江与湖。","哀号浮水出，涕泣通市俱。","抚尸哭一声，痛绝还复苏。","烈士死不悔，妻孥何罪辜！","首祸者谁子？","至今犹缓诛。","椎心问苍天，苍天安足呼！"]},{"t":"震泽 其一","f":"五言律诗","c":["秋风依废寺，拥被听江声。","僧饭临朝绝，梵钟过午鸣。","片烟村树出，一雨板桥平。","赖得漆园叟，摇舟送我行。"]},{"t":"震泽 其二","f":"五言律诗","c":["烽过村村破，叩门我自憎。","平生不信佛，难后每逢僧。","野庙难寻火，深芦时吐灯。","小舟天黑夜，飘泊旁渔罾。"]},{"t":"漫兴 其一","f":"七言律诗","c":["趁艇穿桥去复还，千村今有几村烟！","雪埋橡栗朝无食，风入牛衣夜不眠。","漂母未知亭长厌，野人莫字庾公贤！","荆州御史同为客，独许张融寄小船。"]},{"t":"漫兴 其二","f":"七言律诗","c":["篷窗积雨累旬淹，眼暗河山万恨添。","裹颊几家留郤鉴，叩门何处乞陶潜！","巾裾自取居人怪，面目还遭路鬼嫌。","饮泣江头通不寐，黄星夜夜向南佔。"]},{"t":"徐松涛御史 其一","f":"七言律诗","c":["清秋天外一鸿嘶，万事伤心日落西。","坎路情痴潘岳子，出关肠断伯鸾妻。","麻鞋野阔迷风雨，牛尾江喧乱鼓鼙。","但得追随拚负杖，白云深处好提携！"]},{"t":"徐松涛御史 其二","f":"七言律诗","c":["江村水竹绕茅亭，昨夜还家梦未醒。","楚客到秋容易泣，夷歌杂雨不堪听！","登楼有恨迷王粲，渡海相依仗管宁。","共说避秦闽峤好，夕阳西下武夷青。"]},{"t":"夜渡","f":"五言律诗","c":["辛苦南奔客，宵征寄野航。","作霜片雨住，过水一星长。","人语近溪灭，渔灯出浦藏。","前山闻有火，相戒勿鸣榔！"]},{"t":"睦州道上，示新安穆秀才修玄 其一","f":"五言律诗","c":["万里双芒屩，千峰五尺藤。","水村朝听雨，山店夜留灯。","客病途中健，乡愁久后增。","平生不尽意，辛苦望南兴。"]},{"t":"睦州道上，示新安穆秀才修玄 其二","f":"五言律诗","c":["屈指闽中路，瞻星去转赊。","古桥生石菌，细草结冰花。","绝岭惊人挂，空村怪鸟哗。","吞声是国恨，原不悔倾家！"]},{"t":"衢州遇韦剑威","f":"五言律诗","c":["落魄三衢市，风尘绝泪痕。","对人声尽变，怪我发犹存。","生死浑閒事，衣冠是圣恩。","吴江血已碧，犹是问王孙。"]},{"t":"赠黄仲聚参戎","f":"七言律诗","c":["猿臂开弓三百钧，殿前御试射如神。","黄童本号无双士，先帝亲除第一人。","乱日山城参阃贱，非时旌纛出关频。","将军不羡通侯印，誓复新安把钓纶。"]},{"t":"酬朱润生","f":"五言律诗","c":["汾湖两绝句，一市共悲伤。","难后嗟零落，南来见表章。","黄泉谁寄慰！","青史且输香。","属和篇篇好，吾将罢悼亡。"]},{"t":"三吴兵起纪事，答友人问","f":"五言古诗","c":["昔迎戎师至，兵骄马亦疲。","三吴望风附，弓矢弃不持。","刘生总戎客，船插使清旗。","泊船秀水上，奔竞人恐迟。","刘生不肯仕，心识发且披。","剃发令朝下，相顾为发悲。","三吴同时沸，纷纷起义师。","争言舟楫利，长技不得施！","刘生奔武水，父子就诛夷。","陈梧钱唐至，旋登嘉禾陴。","颇闻黄镇南，驻舟太湖湄。","楼船号万艘，胜兵焉可知！","吴兴馈军粮，昼夜相追随。","壮士争激烈，富室愿蠲赀。","姑苏城门外，匹马不敢窥。","可怜陆太学，破产供军炊。","七月入姑苏，搏战还同嬉。","此辈本乌合，一溃岂复知。","赖有吴职方，稍能出计奇。","伏甲吴江岸，所忌惟在兹。","诸将无斗志，同舟自相疑。","日费千黄金，空养摇橹儿。","嘉禾一夜破，嵩江累卵危。","乞师镇南垒，摇手不可为！","如何十万兵，曾无一矢遗！","括饷既以饱，海口潜奔驰。","海口窄不出，铁骑追及之。","可怜熊虎姿，尽为鱼腹尸！","三吴遍焚戮，试问戎首谁？"]},{"t":"送别穆修玄入大安关","f":"五言律诗","c":["去住凭神决，君侯鉴我诚。","如何今再问，不放与同行！","客路吾谁仗？","他乡别太轻。","故人兹独往，惭愧远来情！"]},{"t":"同韦剑威、徐钦玉度仙霞关 其一","f":"五言律诗","c":["海日埋荒雾，严关已放晨。","行随磨镜客，吟逐讽诗人。","堠草才经火，岩花误作春。","香灯明半岭，争拜五通神。"]},{"t":"同韦剑威、徐钦玉度仙霞关 其二","f":"五言律诗","c":["霞关今重地，度险客心惊。","戍废行人歇，楼荒野雀争。","残虹收鸟外，吼瀑断猿声。","过尽萧条路，将军驻浦城。"]},{"t":"初达行在 其一","f":"五言律诗","c":["万里南奔意，趑趄赴阙初。","功臣营大内，边吏望乘舆。","建武元先改，澶渊诏似虚。","难馀饶涕泪，羞上贾生书！"]},{"t":"初达行在 其二","f":"五言律诗","c":["叩阍书勿信，奇策是虚闻。","我遇出关将，还同霸上军。","吴民真望雨，胡骑尚连云。","莫倚溪山险，端居误圣君！"]},{"t":"放歌，赠吴鉴在","f":"古风","c":["吴生，尔是州来季子裔，我为吴越钱王孙。","我父少年负豪气，尔祖髫龀称弟昆。","尔能下笔风雨惊，我亦有文金石声。","上媲枚、马下李、杜，乡人笑骂两狂生。","狂生挟策天下走，卖赋时人人不受。","武水公子横才名，一听黄钟碎瓦缶。","场前惯赌凉州词，座下频使周颙酒。","诗成笑傲如牛吼，吴侬满前谁开口！","我遭网罗君在疚，海内气数逢阳九。","奸雄坏国国祚移，江南风尘戎马嘶。","子已弃家长千里，我犹浮宅浙水西。","公子倾家建义旗，磨盾草檄鬼神啼。","博浪一椎竟何用，使我妻子并鲸鲵！","鸟惊鱼骇东西逝，我独何辜困吴市！","蒺藜两脚望星奔，子犹待诏金马门。","厨烟萧条雪拥户，相逢一恸怪我存。","以手拭泪泪不止，问我南来何所恃？","赋就难遇狗监荐，粒绝莫送胡奴米。","踉跄导我谒贵人，贵人高卧朝不起。","出门赠我一缗钱，愧彼黔娄反袂死！","吴生、吴生何数奇，我不学入关上书市井儿。","古来圣贤几得志，我死子殡铭我碑！","铭曰「龙眠酒徒湖海士，有才无命如赵岐」。"]},{"t":"故人行","f":"七言古诗","c":["汉家天子重故人，南阳耆旧衣冠新。","羊裘已随安车至，钓滩寂寞谁垂纶！","滹沱麦饭芜蒌粥，黄金大郡报不足。","共称天子笃恩私，努力云台慰主知。","请君试看冯异赐，不是滹沱才过时！"]},{"t":"酬方蕴修","f":"五言律诗","c":["谁失方干意，愁吟动地哀！","言将蹈海去，怪我踏冰来。","威庙怒犹在，孝陵云不开。","伤心是庾信，白发被君催！"]},{"t":"同鉴在、蕴修饮徐闇公司李署","f":"五言律诗","c":["同人不得意，旅食共荒台。","忽有寻梅兴，来衔司李杯。","官清衙吏懒，客散署门开。","独去然灯坐，羡予携手回。"]},{"t":"又示闇公","f":"五言律诗","c":["吾怜徐孺子，亦是英雄人。","爱子殡江寺，故妻还海滨。","都无儿女泪，独有友朋亲。","愧我与同难，终年涕泗新！"]},{"t":"古诗 其一","f":"五言古诗","c":["淮南华橘柚，朱实涵芬香。","得因君子力，委身玉阶旁。","美人出璇户，攀条摘朝霜。","珍盘覆锦绣，置我黄金床。","娇爱不见御，岁宴空自芳。","日闻椒榝充，如何不心伤！"]},{"t":"古诗 其二","f":"五言古诗","c":["苍苍长安陌，郁郁罗青槐。","曜灵生东隅，明堂旦正开。","钟鼓天子坐，冠盖公卿来。","子侯何少年，次第相追陪！","红颜映紫绶，金貂立玉阶。","朝罢骑马还，道旁尽称佳。"]},{"t":"古诗 其三","f":"五言古诗","c":["日落平阳里，王侯相经过。","车马如云屯，葆盖似星罗。","门前列钟鼓，堂上陈笙歌。","华灯灿绮席，珠帘出青娥。","流离曾几时，娱乐何其多！","朝困沙中鳞，夕兴江上波。","得志须尽欢，安能长轗轲？"]},{"t":"古诗 其四","f":"五言古诗","c":["端坐不得志，出门横朱轮。","辉光盈道路，车上意气新。","孙弘起牧豕，买臣方负薪。","一言当天子，遂据要路津。","叱吒奔风雷，顾盼生阳春。","如何贾谊才，终老长沙滨。","丈夫有时命，岂必终苦辛！"]},{"t":"古诗 其五","f":"五言古诗","c":["步出城东门，遥望江南道。","江南何所思？","佳人委秋草。","灵衣张空房，流尘积輀旐。","穗帐明月来，岂若平生好！","葱葱玉树枝，凋摧亦已早。","朝为艳阳花，夕暮成枯槁。","人生少得意，得意难竟保。","弃置勿复思，忧伤徒自老！"]},{"t":"少年行","f":"五言古诗","c":["朝逢游侠儿，鞲靫插羽箭。","放马长楸间，射飞左右便。","气若凌公侯，有技无人善。","上书自请缨，天子不召见。","烽火入萧关，誓与单于战。","白马驮鞍回，霜蹄碧血溅。","生还应无功，死去复谁羡？","少年勇轻生，使我泪流霰。"]},{"t":"侯家行乐词 其一","f":"七言绝句","c":["牙旗鼓角报军门，日午传唤谒至尊。","碧眼横刀还控马，帐前诸将半西番。"]},{"t":"侯家行乐词 其二","f":"七言绝句","c":["鲸波万里入侯封，绝域奇珍大舶供。","漫把黄金沈海底，时教水鬼护蛟龙。"]},{"t":"侯家行乐词 其三","f":"七言绝句","c":["十里香车尽内妆，侯家小女嫁亲王。","雕鞍宝盖明珠络，幔挂珊瑚五尺长。"]},{"t":"侯家行乐词 其四","f":"七言绝句","c":["甲第笙歌早放衙，捲帘深坐尽如花。","专房更数夷王女，閒指扶桑是我家。"]},{"t":"福州迎春歌","f":"七言古诗","c":["福州腊月天气佳，迎春看春人如花。","福州女儿好颜色，皎若朝雪衬轻霞。","宛转蛾眉楼上出，回身却用珠帘遮。","街头小儿喧笙鼓，锦棚对对倡家女。","珠衫宝髻百样装，尽按梨园歌曲谱。","逾梁出卷观者多，却扇亭亭娇不语。","此日梅花满地飞，此时柳色弄春晖。","公子停鞭牵玉勒，佳人对镜换罗衣。","罗衣袅袅细腰身，令人却忆白门春。","白门春在长乾里，钿阁青楼夹道起。","侯家珠翠半天中，外戚帘栊香雾里。","三条九陌车骑纷，人影花光何处是！","杨柳溪边岁岁新，射雕今已遍城闉。","秋千院下穹庐帐，蹴鞠场飞铁马尘。","可怜日暮吹笳动，风杂鸦声愁杀人！"]},{"t":"寄孙克咸 其一","f":"五言古诗","c":["夙昔同枝鸟，猋如浮尘散。","何意天涯身，与子复同难！","念我掌中娇，对面相糜烂。","咫尺不得救，空使肝肠断。","馀命锋刃残，分飞互零乱。","我寻闽峤烟，子矫越水翰。","冉冉孤云行，杳杳子规唤。","相望不相闻，因风发长叹！"]},{"t":"寄孙克咸 其二","f":"五言古诗","c":["黄星耀闽海，紫盖辉越东。","思君兄与弟，冥若云中鸿。","诏书屡慇勤，高尚讵能同！","俊杰识时务，君子凛固穷。","君闻在幕府，颇立文若功。","鄙志循斗筲，抱关息微躬。","愧尔百炼钢，秃首甘从戎！"]},{"t":"授官后，呈黄石斋、曾二云两师","f":"七言律诗","c":["艰难雪窖向南奔，万里惊看双笔存。","却幸荐由文举牍，更怜身出陆公门。","浮名海内今谁在？","吏道中朝久不尊。","啸傲半生成小草，好持冰蘖报师恩。"]},{"t":"入虔次芋园驿，同方蕴修守岁刘中丞远生昆仲寓中","f":"五言律诗","c":["万里依刘表，天涯渡汉年。","海灯千帐静，画鼓一更传。","花媚江南客，杯衔渭北筵。","与君皆只影，益羡二难贤！"]},{"t":"丙戌元旦，同远生芋园驿作","f":"五言律诗","c":["海驿逢新岁，椒畅万里情。","朝元随幕府，庆节听班声。","小吏朱衣试，戈船画帜更。","还瞻葱郁气，正满建安城。"]},{"t":"亡妇方氏得恤","f":"五言律诗","c":["为诉吴民痛，终言家难婴。","君王重节义，匹妇有褒荣。","萤火光犹灿，鸿毛死未轻。","更怜诸烈妇，谁与更陈情！"]},{"t":"饮陈道掌留别","f":"五言律诗","c":["廿年湖海士，一卧鬓华新。","雅好陈遵客，羞言原宪贫。","天涯离别夜，辇下病残身。","章、贡邮传便，毋难讯字频！"]},{"t":"奉别朱文园先生入虔","f":"七言律诗","c":["潦到文场二十秋，难馀偶被药宠收。","朝廷多故官难择，科举成名志已休！","小草愧虚知己望，铅刀妄拟圣恩酬。","即今匹马青烽外，惭负先生绛帐留！"]},{"t":"张将军蒐乘歌","f":"古风","c":["张将军、张将军，身长七尺面如银。","裲裆绣髯蛮靴窄，于阗腰带方麒麟。","登坛年才二十春，号令三军若鬼神。","霜戈雪戟貔虎队，角声三绝寂无人。","旌旗展动开八门，青龙朱雀五方分。","五方壁立人如植，匹马周巡不起尘。","红旗一点兵纷纷，有若风起旋秋云。","东西羽毛倏改色，蛇鸟变化一时新。","此是鸳鸯阵，忽成鹅鹳群。","颐指目动列校奔，将军据地声不闻。","鼓声既绝金钲鸣，阵色次第收霞纹。","张将军，良苦辛！","棘门、灞上久儿戏，中原坐视沧海沦。","子有纪律兵必精，为我出兵收两京！","关内耀兵有诸君，子奏云台第一勋！"]},{"t":"石牛驿","f":"七言古诗","c":["石牛驿破存两楹，鸟雀满地无人声。","客子入门风淅淅，停车下马不得行。","隔墙叫怒如哮虎，银铛锁吏出废堵。","鞭笞乱下冤不闻，良久叩头诉其苦。","自从江、楚纷用兵，分符秉钺输蹄横。","已愁宾客多需索，更苦刁阉难逢迎。","朝啼卖女夕卖妇，饥肤戕毁复何有！","供顿王官职所当，白板公卿费奔走。","昨日负薪者竖儒，挽牛入关窃上书。","此辈宁有安刘计，今来驰驿事恣睢。","官家但识遣使臣，那知驿吏多苦辛！","朝廷克敌须庙算，岂在多用虚言人！"]},{"t":"同远生中丞入虔道上杂作 其一","f":"五言律诗","c":["入关魂未定，挟策更从军。","影去鹓鸾队，声迷鹅鹳群。","旌旗山雾避，铙吹海神闻。","聚米谈兵夜，边才合让君。"]},{"t":"同远生中丞入虔道上杂作 其二","f":"五言律诗","c":["鹢首乘潮上，旗门映日飏。","家僮传画鼓，剑客挽牙樯。","星宿缠营火，鱼龙趁甲光。","晚来亲出射，夹岸列鸳鸯。"]},{"t":"同远生中丞入虔道上杂作 其三","f":"五言律诗","c":["山深物候早，一路莽春声。","谷鸟迎人立，岩花问客名。","驿疲军使缓，县远戍灯明。","庙议忧江、楚，慇勤此路行。"]},{"t":"同远生中丞入虔道上杂作 其四","f":"五言律诗","c":["磨盾非吾事，看山似夙游。","笋舆千壑转，官路万松稠。","雾散溪声骤，鸟鸣新雨收。","无劳讯候吏，风物是汀州。"]},{"t":"同远生中丞入虔道上杂作 其五","f":"五言律诗","c":["虔州天下险，今见郁孤台。","甲仗排云出，戈船挟雨来。","戍楼旗尽变，驿路草新开。","军吏班声远，争知陆逊才。"]},{"t":"沙边老人行","f":"古风","c":["母声求子妻求夫，雨中藉藉走且呼。","沙边老人叩头诉，言是四营兵过城东隅。","四营萑苻小盗贼，窜伏溪洞逃天诛。","自下黄纸招降诏，召集乡里千百俱。","昔掠村野不近郛，今移全营逼通都。","又闻受抚不受约，白昼带刀街头趋。","街头公然掠小儿，劫夺不与盗贼殊。","满郊耕牛脯作饭，官家秋来宁蠲租！","往时交战被我俘，今名「激叛」罹罪辜。","梅林截渡不放过，室庐遭毁人遭屠。","谁为朝廷画此策，云欲招抚收两湖？","此辈小丑何足战，徒虐乡里荣其躯！","老人不必涕交须，绿林青犊古来用，功成不扰理所无！","尔不闻诏书久悬晋贤爵，乘舆早晚跸洪都？","尔诉所痛何区区！"]},{"t":"楼船行，赠杨清江相公","f":"七言古诗","c":["北风吼江江怒旋，巨舰山齐万锁连。","牙旗百丈飏天半，相公秉钺坐楼船。","楼船鹢首排霜戟，吹铙击鼓辕门辟。","裘带逍遥如意閒，顾盼神明髭半白。","相公年才四十强，当时对策擅明光。","集贤学士争辟易，上书请缨何慨慷！","子云嗜奇羞节义，伯起强项愧文章。","渔阳马尘飞左右，十二城郭尽拱手。","褒衣大颡奋袖呼，吉安夜复临江走。","捷奏灵武叹奇勋，黄麻诏下五华云。","锋车屡趣不肯入，仍请节钺领三军。","敕兼将相三军喜，相公终岁楼船里。","呱呱幼子托门人，爱妾山中饥冻死！","家信从来不敢传，秋灯霜鬓独筹边。","暇时自写铙歌曲，鸾翔凤翥势翩跹。","如今幂府无成策，望公开阁延奇客！","如今诸将有先声，望公勿用绿林兵！","楼船一出恢江国，直下石头收旧京！"]},{"t":"江涨","f":"五言律诗","c":["建瓴章、贡水，一雨两江通。","列舰冲潮乱，孤城听吼雄。","响高天上怒，波急月中红。","此际楼船发，乘风好奏功！"]},{"t":"江雨，赠延安刘客生卧病 其一","f":"七言律诗","c":["鶗鴃初鸣村雨斜，吉州烽火暗天涯。","留侯借箸身多病，庾信伤心鬓早华。","半夜吹灯重煮药，三春掩袖忍看花。","扣舷泪溅双流水，渭北、江南何处家？"]},{"t":"江雨，赠延安刘客生卧病 其二","f":"七言律诗","c":["江高响急客愁新，白舫青囊又浃辰。","辛苦樯鸠勤祝雨，浮沈波鸟漫亲人。","篙师水调声声楚，军吏边装处处秦。","旌节淹留缘底事？","羽书今已隔三春！"]},{"t":"客生梓石映昆遗稿成，属予为序。因题其后 其一","f":"五言律诗","c":["万里南奔客，捐躯已一年！","可怜遗稿在，犹荷故人编。","佳句风尘得，穷途意气偏。","平生文散尽，留取姓名传。"]},{"t":"客生梓石映昆遗稿成，属予为序。因题其后 其二","f":"五言律诗","c":["北阙上书罢，梦魂空入关！","正逢南渡日，羞厕进贤班。","童仆依人在，家乡望汝还。","江头殡旅榇，谁与返秦山！"]},{"t":"赠杨幼于给谏","f":"五言古诗","c":["杨子流三吴，烟尘罹家患。","泛海入闽来，涕泣授给谏。","衔诏赴荆南，憔悴衣履绽。","何意章、贡烽，竟阻衡阳雁！","攘袂誓登陴，甲冑亲自擐。","壮士勇为鼓，戎器徐亦办。","屡战摧敌锋，咬指西山瞷。","守将弃城奔，保障属游宦。","乃知将军印，古来书生绾！"]},{"t":"从军口号 其一","f":"七言绝句","c":["已闻骠骑援兵至，髵䰄遥见探马还。","夜半火行营尽动，一时移帐过西山。"]},{"t":"从军口号 其二","f":"七言绝句","c":["日落沙飞战鼓嚣，过河犹听马蹄骄。","前山探卒宵来报，三两胡雏学射雕。"]},{"t":"从军口号 其三","f":"七言绝句","c":["伏弩缘堤间炮台，天骄十骑渡河来。","同时水陷埋沙渍，不肯乘危放尔回。"]},{"t":"从军口号 其四","f":"七言绝句","c":["西山入夜起歌声，掠得佳人酒压惊。","醉卧帐前浑似死，曾无一将说偷营！"]},{"t":"从军口号 其五","f":"七言绝句","c":["胡雏饮马傍江汀，炮火雷轰似不听。","骑马欲回还下坐，山颠去放海东青。"]},{"t":"从军口号 其六","f":"七言绝句","c":["连朝鼓角震山阿，一夜沙场鬼火多。","月照汉家营悄悄，隔河拍手唱夷歌。"]},{"t":"虔州即事 其一","f":"七言律诗","c":["拂地骄鹰暗虎头，锦貂公子梦封侯。","杏花落尽田难种，布谷鸣残麦未收。","铜马讵能扶赤伏，黄州曾可号青州？","江村野哭声声苦，独赋「登楼」悔久留！"]},{"t":"虔州即事 其二","f":"七言律诗","c":["吉州烽火照江干，一夜腥风江水寒。","急撤万安防皂口，早催章、贡下棉滩。","云南戍卒全营去，「龙武新军」驻马看。","独见尺书来幕府，誓将坚卧砥狂澜。"]},{"t":"虔州即事 其三","f":"七言律诗","c":["南、诏诸军去不回，狼兵才费羽书催。","棉津天堑全虚设，章、贡孤城迥自开。","中丞屡下徵师檄，司马难登誓将台！","唯喜临江杨相国，亲提鹅鹳向东来。"]},{"t":"虔州即事 其四","f":"七言律诗","c":["西山麾帐迥连云，倏忽猋骑数百群。","营火依星明彻夜，角声向月惨难闻。","父书尽弃长平卒，儿戏羞称灞上军！","自笑腐儒无七略，铙歌检出背人焚。"]},{"t":"虔州即事 其五","f":"七言律诗","c":["旌竿袅袅隔城东，代马临江壁已空。","赤祲满天休望气，黑云压阵更佔风。","牙旗早失刘开府，金印新悬张总戎。","此日穹庐犹遍野，殊恩漫锡守虔功！"]},{"t":"鹡鸰行，赠刘客生","f":"古风","c":["中庭有佳树，两鸟鸣高枝。","毛羽既相类，声音亦参差。","摇尾踯躅鸟心乐，刘生听之心伤悲。","刘生关西游侠子，兄为中丞弟御史。","中丞开府亲握兵，生也谢病卧虔城。","渔阳马飞章贡城，胡兵百战汉兵新。","江右诸将少节制，廉颇空思用赵人！","鼓声才接列校奔，按剑独有中丞存。","楚师乘胜得知武，宋人弃甲失华元。","朝廷是非竟安在，守城论功战者罪。","赐印益令逃将骄，蠲躯徒使英雄悔！","刘生、刘生哭勿哀，友恭自是天性胎。","泣血常知寝处湿，上书屡为时相猜！","尔不闻信国被擒航海脱，李广遭缚夺马回？","忠孝自获神明助，中丞不死突围来！"]},{"t":"会昌遇姚二存御史，与谈虔事","f":"五言律诗","c":["暂驻青骢马，虔州我近过。","大都堪将少，无取调兵多。","万幛缠西岭，孤城阻尺波。","诸军非百战，此去欲如何！"]},{"t":"长汀道中示吴二明府 其一","f":"七言律诗","c":["驿路凋残何处行，又穿烽燧赴荒城。","渡头虎迹沿溪去，村外鸡声冒雨鸣。","鸟帽即今双短鬓，青山依旧两狂生。","相看漫洒吴江泪，已听褒纶赠杲卿！"]},{"t":"长汀道中示吴二明府 其二","f":"七言律诗","c":["炊烟泄处指单车，落落风流想孟嘉。","荒涧暗生江岸草，野田閒放故园花。","民因兵乱稀开肆，吏以官清早放衙。","见说折腰终日苦，微霜已点鬓边华。"]},{"t":"哭漳浦师 其一","f":"七言律诗","c":["宣麻几日点朝班，谁遣单车自出关？","久信赤符成两汉，空佔紫盖照三山！","总戎已弃全军遁，丞相何难匹马还。","长啸请缨虚有愿，惟馀涕泪洒龙颜！"]},{"t":"哭漳浦师 其二","f":"七言律诗","c":["去岁吴门已变名，市中卖饼识邠卿。","曾将逃死嗤张俭，何取狂生荐祢衡！","南极有星通夜动，天隅一柱早时倾。","入关狼狈音容阻，回首铜山哭几声！"]},{"t":"哭漳浦师 其三","f":"七言律诗","c":["二月长干天昼昏，都人争举李膺幡。","笑将涕泪酬知己，坐索衣冠谢主恩。","无路请还先轸首，何人招返屈原魂！","当年北寺留皮骨，此日南朝仗尔存！"]},{"t":"酬开少 其一","f":"七言律诗","c":["三十年来钱起名，登坛不用一军惊。","皂囊草出宫中诵，铁笔书成海外行。","慷慨阿兄真御史，飘零小弟旧狂生。","凭君早赞兴刘业，给札兰台赋「两京」。"]},{"t":"酬开少 其二","f":"七言律诗","c":["汉廷党祸几人馀，国覆君亡禁甫除。","北寺已成元礼狱，西行谁上贾彪书！","淮南幕启借前箸，武水壁深开后车。","二竖至今为国祟，埋轮不问欲何如！"]},{"t":"酬开少 其三","f":"七言律诗","c":["吹笳放畜遍长洲，洒泪逢君泖上舟。","战鼓魂销莺脰月，义旗风卷鹤湖秋。","袖藏沧海枪犹在，衣溅吴江血未收。","每过乌台添往恨，几回掩面哭西州。"]},{"t":"酬开少 其四","f":"七言律诗","c":["遍舟震泽去难攀，皂帽单襦自入关。","客路行歌逢鬼笑，邻樯辨语识生还。","同来仗策推公瑾，独赋伤心是子山！","待诏半年徒寂寂，谏章时为破愁颜。"]},{"t":"读开少御史谏章漫书","f":"古风","c":["吾家有仲文，风流擅文赋。","横被党人名，钩校同我锢。","吴江举义师，竟被楼船误。","脱身西入关，上书蒙奇遇。","片言赐豸冠，宰相苦见妒。","吾兄勇报恩，有怀无不吐。","会稽初入国，冀马方东渡。","恤邻宜见哀，况乃唇齿傅！","如何元子诞，封爵遍?䪒。","称觞拜新恩，举朝懵不寤？","一疏破迷群，遂使主人惧。","谏章满皂囊，兹当推独步。"]},{"t":"萃士歌","f":"七言古诗","c":["中兴圣人重文墨，取士耻循旧资格。","上书召对无奇才，储贤有馆空自开。","庭试诸生本故事，亲拔明经称萃士。","木天教习随庶常，梧垣径授宠莫当。","传闻馆课兼风雅，可怜萃士无知者！","羽书已报东吴失，萃士初学调音律。","为语萃士学勿迟，关外需君退虏诗！"]},{"t":"陈将军","f":"古风","c":["行宫门外人纷纷，争传看杀陈将军。","郑家勋侯上殿救，天子两耳塞不闻。","天子英明文且武，勋侯难挽雷霆怒。","必罚用惩东向心，伤恩岂顾北道主。","自从登极行天诛，西市骈首阿大夫。","今年二竖冒官职，即时赐死冤谁呼！","从来乱国用重典，将军观望那得免！","君不见郑家出抱将军尸，颈血淋漓亲为吮？"]},{"t":"越东破","f":"古风","c":["当今天子高皇孙，鲁国同是至亲藩。","改元本非利天下，域内原宜奉一尊。","越东君臣殊可笑，誓死不开登极诏。","天子洒笔亲致书，相期先谒高皇庙！","闽中恃越为藩篱，如今越破闽亦危。","往时纷争不足论，与国既失应同悲！","昨夜室中诞元子，通侯鹊印何累累！","中兴所重在边疆，恩泽滥冒同烂羊。","唇亡齿寒古所忌，君不闻元子之诞唇先亡？"]},{"t":"延平寄客生、鉴在","f":"五言律诗","c":["时事竟难论，秋来悔此行。","一官叨半刺，万乘倚孤城。","井邑声朝杂，关门火夜明。","知君悲海市，游戏笑狂生。"]},{"t":"初见朝恭纪","f":"五言律诗","c":["钟报御门早，朝趋受命初。","府僚班苦后，天语听全疏。","庭宣迎驾表，帕覆出关书。","中使传烧却，君王度有馀。"]},{"t":"行朝过袁太常特邱 其一","f":"七言律诗","c":["阊阖遥遥稽首还，侍臣剑佩近难攀。","声音旧识袁临汝，须发遥惊庾子山。","薄宦生涯随马足，青云咫尺隔鹓班。","簪缨聚首真疑梦，泪尽烽烟一破颜。"]},{"t":"行朝过袁太常特邱 其二","f":"七言律诗","c":["端笏垂金老奉常，新诗犹记咏吴阊。","佩环响自先朝旧，须鬓丝由渡海苍。","强项可怜淹小草，故人曾许荐长杨。","当时复壁相持泣，回忆江南泪几行！"]},{"t":"延平书怀","f":"五言律诗","c":["江潭新叶落，庾信迥添愁。","门掩千家雨，寒归万井秋。","戈船横浙水，铁骑绕虔州。","昨夜金章下，传封恩泽侯。"]},{"t":"行延平诸县即事 其一","f":"七言律诗","c":["匹马秋来趁落霞，风尘自笑老生涯。","乌啼似拥山城鹊，菊碎初开小县花。","渡口渔人收晚棹，沙头津吏候征车。","昨来野店频投宿，记在桥南三两家。"]},{"t":"行延平诸县即事 其二","f":"七言律诗","c":["画毂无歌行路难，连朝星露点征鞍。","江城鱼火通沙县，山郭园林入永安。","老吏漫持秦法律，诸生还睹汉衣冠。","太平风景无多处，竹马儿童仔细看。"]},{"t":"八月十七日哭仲驭 其一","f":"七言律诗","c":["去岁兹辰绝命年，椎心不敢恨苍天。","定知叔宝神难寿，虚拟相如病未痊。","血溅长堤留碧草，魂归小阁亦青毡。","哭君一字肠堪断，夜半山空叫杜鹃！"]},{"t":"八月十七日哭仲驭 其二","f":"七言律诗","c":["园林回首最堪悲，别院新开病起迟！","瘦骨岂知埋马革！","壮心不分死蛾眉。","伤予竟丧童乌子，痛汝曾无伯道儿！","南院荒凉成废宅，哀哀寡妇哭江湄！"]},{"t":"八月十七日哭仲驭 其三","f":"七言律诗","c":["义公初建鹤湖旗，海邑江城檄遍驰。","亡晋尚挥夷甫麈，报韩独购子房椎。","佯狂破产庸儿笑，涕泣蠲租壮士悲。","赢得「太常」身后恤，孤忠原不望人知。"]},{"t":"八月十七日哭仲驭 其四","f":"七言律诗","c":["事去同舟祗腐儒，灯前对语惜汾湖。","从军快得陈书记，妖梦何来骆义乌！","夜雨尸沈呼自出，秋山榇返仗谁扶！","青衫滴尽伤心泪，哭到妻儿泪已枯！"]},{"t":"伤心诗 其四","f":"七言律诗","c":["朱颜回忆画堂新，辛苦牛衣二十春。","求婿每惭郤鉴赏，改妆宁为鲍宣贫。","车裘赠我成游子，甘脆劳卿奉老亲。","旧是狂奴今作吏，琴书检点仗何人！"]},{"t":"伤心诗 其五","f":"七言律诗","c":["书生横负党人冤，寒腊追寻两雪繁。","岂为伯通舂可赁，祇闻宾硕壁堪存！","鹿车千里共亡命，鱼艇三江莫返魂。","每忆谢庭兄弟好，教人何处恨章惇！"]},{"t":"伤心诗 其六","f":"七言律诗","c":["乱去凌霜志苦坚，褰衣誓死自年年。","贞心早兆庐居梦，幽恨难旌节母贤！","震泽尸浮通市泣，汾湖诗出万人传。","太常一字芳魂慰，列传何时付史编！"]},{"t":"自永安返至贡川闻延平信，示诸吏佐","f":"七言律诗","c":["蜃楼燕幕等閒看，独笑忧天泪未乾。","仍著芒鞋寻鸟道，早抛华组系渔竿。","朝霞已逐浮云散，夕露应同逝水寒。","我自行歌卿自去，好持刀笔事秦官！"]},{"t":"贡川闻王郡伯死，为位哭之","f":"五言古诗","c":["大运岂遽非，哲人遂云徂！","我见谋国臣，太息无良图！","岂意匹马来，开门纵长驱。","争降何纷然，常恐后至诛！","贤哉二千石，从容捐厥躯！","夫子庄而简，薄官初剖符。","不谓贞松姿，临难表所殊！","独湔嵇绍血，莫污温序须。","我生既已幸，我志宁可渝！","乘舆咫尺间，岂复辞崎岖！","回脰望延津，吁嗟烈丈夫！"]},{"t":"广文歌","f":"古风","c":["广文先生老且贤，角巾已破乌皮穿。","执板折腰殊不谙，见人木强无周旋。","盘桓苜蓿风尘陡，招降使者声如吼。","箕踞学宫召诸生，问渠广文不开口。","振袖大骂杯掷空，区区头颅复何有！","宣圣昔却莱夷戈，子羔肯由狗窦走？","君不闻鬷蔑一语叔向倾，毛遂捧槃平原惊？","丈夫意气临危见，岂在人貌与荣名！"]},{"t":"黯淡滩","f":"七言绝句","c":["方帅穷归应藁竿，更诛马相七闽欢。","严州阁老降何事，白首同悬黯淡滩！"]},{"t":"予既别永安山中，间道走汀州，路阻不前。诸友有招予还者，兼和鄙韵见寄。赋此志谢","f":"七言律诗","c":["西风吹客出岩阿，自别松关涕泪多。","鹤梦不曾离瀚海，猿声长记挂藤萝。","近春村暖花全白，入夜愁侵鬓已皤。","属和应多亡国恨，可能击筑共悲歌！"]},{"t":"无题 其一","f":"七言律诗","c":["鄞江消息定如何，怅望旌旗洒泪多。","野戍啼乌迷汉帜，荒城残月起夷歌。","稽山无计栖句践，南粤宁同王尉佗！","谷鸟催人头白尽，声声长在向南柯。"]},{"t":"无题 其二","f":"七言律诗","c":["山深辇路费春锄，江、楚遥遥望属车。","岂有千官怀去就，翻劳万乘久踌躇。","朱提喜赐儒生对，黄帕传看边吏书。","廷议半年长不决，澶渊亲诏已全虚！"]},{"t":"无题 其三","f":"七言律诗","c":["去日追班入紫宸，花间鹓鹭片时亲。","纶扉白发南阳旧，侯印黄金恩泽新。","羽檄遥知边奏至，龙颜时向内家颦。","自闻东越唇亡后，早使忧天泣小臣。"]},{"t":"无题 其四","f":"七言律诗","c":["光禄蔬盘出尚方，柘枝新染布袍黄。","威仪已睹汉司隶，边幅还嗤蜀子阳。","书载五车分秘阁，手裁三诏压明光。","六龙此日无消息，夜半占星泪几行！"]},{"t":"鄞江怨词 其一","f":"七言绝句","c":["六龙空驻禁城傍，铁骑宫前射锦珰。","隆准奇姿人尽识，谁为纪信代君王？"]},{"t":"鄞江怨词 其二","f":"七言绝句","c":["此日君王行路难，穷庐犹献八珍盘。","金钟玉箸髵䰄进，岂似伊蒲出大官！"]},{"t":"鄞江怨词 其三","f":"七言绝句","c":["日落三山烽火迷，乘舆说共左贤栖。","长安不作青衣恨，夜半微闻杜宇啼。"]},{"t":"鄞江怨词 其四","f":"七言绝句","c":["龙旗何处久淹留，手诏频传催大侯。","今日蒙尘栖毳幕，元勋先已著毡裘！"]},{"t":"宫词六首 其一","f":"七言绝句","c":["内使承恩新置机，诏传大布织龙衣。","六宫罗绮无人著，敕与元戎绣将旗。"]},{"t":"宫词六首 其二","f":"七言绝句","c":["光禄虚闻进八珍，君王蔬食已多春。","黄门小竖閒锄地，御苑时供菜甲新。"]},{"t":"宫词六首 其三","f":"七言绝句","c":["宫漏沈沈迥未眠，大家秉烛在甘泉。","遥瞻御笔珠帘里，夜半频闻手诏传。"]},{"t":"宫词六首 其四","f":"七言绝句","c":["旌旗十万护乘舆，二圣军中共起居。","长信宫人骑马出，从龙祗有五车书。"]},{"t":"宫词六首 其五","f":"七言绝句","c":["外廷章奏晚犹通，侍史开封五夜同。","传道君王看不及，黄罗亲裹送中宫。"]},{"t":"宫词六首 其六","f":"七言绝句","c":["朝看佛院有辉光，敕使传烧内殿香。","日午宫中双辇出，金莲影里拜空王。"]},{"t":"闻客生昆仲入粤，予子法祖随焉。鉴在、蕴修、坤丞应相携同去，予独留滞闽乡，诗以写怀 其一","f":"七言律诗","c":["乱去交亲少昔欢，天涯羁旅足盘桓。","故乡竹马存三子，海内求羊有二难。","绝岭驾风秋雁远，空山叫月夜猿单。","南雄路断音书隔，惆怅梅花不忍看！"]},{"t":"闻客生昆仲入粤，予子法祖随焉。鉴在、蕴修、坤丞应相携同去，予独留滞闽乡，诗以写怀 其二","f":"七言律诗","c":["家难倾巢一子全，提携虎穴仗诸贤。","定知卵翼危难弃，无那乌栖夜不眠！","万死幸留书种在，半生赢得故人怜。","皖江书讯今年到，迟尔还山治墓田！"]},{"t":"得孙克咸死难信 其一","f":"五言律诗","c":["不讯孙嵩久，疑君变姓还。","关门人渐至，死丧信初传。","血化空山火，魂依子夜鹃。","平生谈侠气，草草一躯捐！"]},{"t":"得孙克咸死难信 其二","f":"五言律诗","c":["怜君多绝艺，未乱喜从戎。","死夫人为戒，招来鬼尚雄。","老妻能咏絮，爱子善弯弓。","玉树同摇落，飘零何处风？"]},{"t":"得孙克咸死难信 其三","f":"五言律诗","c":["回忆同游地，东门路可悲！","闺人传道蕴，天坏笑凝之。","兴在江湖短，情因儿女痴。","谢家兄弟好，几处哭新诗！"]},{"t":"得孙克咸死难信 其四","f":"五言律诗","c":["吴江同难后，闽、越各天奔。","巢卵悲予破，掌珠羡尔存。","两年重落魄，万里一游魂。","地下逢殇子，通家有旧恩。"]},{"t":"有所闻作 其一","f":"七言律诗","c":["戎旆迟迟迥不舒，闽江村郭半成墟。","浪闻扶义称铜马，喜听蒙尘是副车。","五岭山川百战后，三湘壁垒十年馀。","愁时目断南飞雁，莫寄孤臣雪窖书！"]},{"t":"有所闻作 其二","f":"七言律诗","c":["单于腊火照关门，撤尽防兵野戍存。","岭娇已凭驱铁马，海天何事竖降幡！","甘辞义士田横岛，漫负通侯汉主恩！","此日穷庐归未得，绝班可似故年尊？"]},{"t":"除夕","f":"七言律诗","c":["柏酒凄凉独夜杯，灯花双穗向谁开？","天边雁阵飞难到，海上龙旗去不回！","旅榇久抛吴地草，孤儿遥泣岭头梅。","侧身西望湖湘远，空有人传将相才！"]},{"t":"哭曹能始先生","f":"七言律诗","c":["颜远诗名四十年，风流今借义声传。","独留霜发还家庙，不遂潮头上海船。","万卷书随神女散，一家忠动敌人怜。","九原绝少同乡伴，犹赖延平太守贤。"]},{"t":"闻人述浦城近事，慨然伤之","f":"七言律诗","c":["仙霞关上雁来稀，碧血惊闻溅绣衣。","汉节不随秋草没，胡笳竟逐塞尘飞。","甘心息妫雠何论，绝意文君赎不归。","臣节已完吾事毕，苏卿岂问去妻帏！"]},{"t":"人来说岭南事，怅然述怀","f":"五言律诗","c":["半年庾信梦，消息竟全虚！","百粤应难去，双峰从此居。","也闻称正朔，何计觅乘舆！","羡尔云中翼，因风寄帛书。"]},{"t":"痴虎行","f":"古风","c":["南山有猛虎，端坐岩穴间。","南山石齿齿，岩穴谁跻攀！","世人未睹爪牙利，惊传猛虎色斑斑。","五陵少年素趫捷，见虎不出知虎怯。","腰弓插羽鞲苍鹰，凌冬却上南山猎。","玄猿青兕蹴踏平，虎昔无迹今无穴。","苍苍落日满山谷，欲行取虎畏虎伏。","牵羊为牲犬豕随，前往虎穴饲虎饥。","虎饥求食出何急，少年一麾生致之。","嗟哉虎何痴！","蛟龙勿失江湖波，虎豹势在深山阿。","深山盘盘守尔拙，少年趫捷奈尔何！"]},{"t":"虔州行","f":"古风","c":["烟冥冥，雨啾啾，黄昏鬼火遍城头。","行人白昼不敢过，问之乃是昔虔州。","虔州地形控江、楚，关税兼通闽、越贾。","船上珍珠不值钱，城中养女能歌舞。","闾阎扑地楼插天，家家日暮喧笙鼓。","渔阳白马动地来，中原十城九城开。","吉安已破皂口失，孤城水上空崔嵬！","铁骑连山风雨集，炮火塌天城不摧。","城头壮士不畏死，夜半缒城砍敌垒。","腰间夺得乌孙刀，背上插来白羽矢。","紫髯将军不敢逼，立马西山时咋指。","城悬粮绝无援兵，四面尽是吹笳声。","初犹食马后食人，登楼击鼓鼓不鸣。","朔风吹雪酒盏大，守陴人病三日饿。","遥见营火渡河来，一半传更一半卧。","兵声暗绝风雨声，五更未醒虔州破。","闭城刈人人莫逃，马前血溅成波涛。","朱颜宛转填眢井，白骨撑拄无空壕！","自从司马誓城守，老弱登陴谁敢走！","清江、龙泉居上游，突围入城今在否？","诸君磊落忠义人，死去名节千秋新。","可怜虔州十万户，日暮飞作沙与尘！"]},{"t":"哀江南 其一","f":"五言古诗","c":["太宰四朝遗，清风三十载。","一秉南渡铨，期月遂得罪。","既遭党人摈，还嗟国事殆。","虏至阖城奔，公也入城待。","所耻临难免，庶无见危悔。","衣冠殉家庙，十日颜不改。","忠义及仆夫，哀歌动横海。","谁谓伯道孤？","神明故长在！"]},{"t":"哀江南 其二","f":"五言古诗","c":["天下刘夫子，节义岂所论！","直道朝廷黜，绝学海内奔。","东南人才薮，贤者游其门。","绝粒殉国难，七日息犹存。","王生本高足，振袖赴清源。","上书促夫子，先期于九原。","三叹亦殒命，无愧知己言。","王生义诚烈，夫子道益尊！"]},{"t":"哀江南 其三","f":"五言古诗","c":["詹事秀吴阊，扁舟拂袖早。","诗酒怡良朋，丝竹娱遐抱。","如何峰、泖间，不问入山道！","胡尘渡江昏，姱修闭门保。","辫发号国门，洁身赴池岛。","腥风虽满城，沈沙独皓皓。","人生足荣名，得死乃为宝。"]},{"t":"哀江南 其四","f":"五言古诗","c":["侯公薄仕宦，闭户天伦笃。","介弟振南金，令子森昆玉。","桃李遍江城，文章化风俗。","狄氛一朝狂，名德苦见辱。","仗节哲人先，象贤清白续。","宁为芝兰摧，不同萧艾蓐。","阖户以成仁，孤忠向谁告！"]},{"t":"哀江南 其五","f":"五言古诗","c":["磊落祁中丞，骨鲠豪强避。","謇谔西台简，澄清东吴辔。","东吴借开府，苦被党人忌。","解组渡钱唐，胡马长驱至。","膻氛虽未侵，洁身早为智。","儿女空攀号，莫慰哲人意。","浩浩托身澜，乘间乃得遂。","袍笏俨平生，真气犹高视。"]},{"t":"哀江南 其六","f":"五言古诗","c":["学士好禅定，报国亦讲武。","木天请缨出，志抗城下虏。","厥功虽不成，天子髀尝拊。","归田颇寓兵，还遭绛灌怒。","义旗倡天都，严关飞鸟阻。","一呼百万饷，侠哉新安贾。","奸人半夜回，公志竟中沮。","可怜江文学，奋身赴死所！","大义激孤忠，肯为甘言取！","一死报里人，不负平生许。"]},{"t":"哀江南 其七","f":"五言古诗","c":["考功人伦表，名德冠东南。","物望被钩校，时议早抽簪。","潜居泖水滨，轩户临清潭。","与我开轩坐，羡此碧于蓝。","曰予效怀沙，魂魄亮所甘！","秋风马嘶急，斯言果不惭。","贞白贻千秋，泖波同湛湛。"]},{"t":"哀江南 其八","f":"五言古诗","c":["吏部武肃裔，通籍甫弱冠。","请养旋居庐，风雅窥周、汉。","岂意永嘉徒，顿召戎狄乱！","家世荷深恩，誓与国同难。","破产壮士归，努力相国赞！","诸将非战才，财匮师亦散！","独有三儒生，对泣汾湖畔。","田税蠲勿收，家书烧不看。","震泽仓卒行，死生顷刻判！","我来号其尸，从容出湍澜。","小竖死持裾，截流随登岸。","市人相聚观，啧啧发长叹！"]},{"t":"哀江南 其九","f":"五言古诗","c":["职方雅学武，临敌辄身先。","芦中伏犀甲，时时夺戈船。","大运既以非，孤军岂独全！","阖门罹锋刃，栖身穷山巅。","如何同袍友，机阱构宾筵！","所悲壮志尽，宁惜一躯捐！","亦有孙公子，帷幄共周旋。","事败誓同归，难至耻苟全。","面数负恩酋，言之罪通天。","义气两无负，哀哉此二贤！","昔有卢司马，才气当代雄。","身骑生力驹，手挽五石弓。","群贼奉首窜，命在破竹中。","朝廷用不专，草草殒厥躬。","介弟早登第，毅然哲兄风。","弃家阳羡山，树帜太湖东。","跃马亲搏战，斩获屡建功。","马疲兵亦散，大命乃遽终！","可怜司马家，一门著双忠。","兄弟死国难，信与二颜同！"]},{"t":"哀江南 其十","f":"五言古诗","c":["我昔游钱塘，缟纻何缤纷。","大行赋豪气，顾盼凌青云！","呜呼钱塘破，抗义无一闻！","吾子先几决，超然绝尘氛。","临决亦有约，一死真伪分。","贤偶殉所天，闺阁同清芬。","哲兄奉寡母，抚尸悲且欣。","闭门养亲志，饥寒甘卖文。","卓哉此二陆，机、云安足云！"]},{"t":"哀江南 其十一","f":"五言古诗","c":["黄子气萧瑟，颇悟微言旨。","举业冠本朝，先辈谁可比！","一第归著书，十年期读史。","痛绝鼎湖髯，南渡徵不起！","虏氛暗吴来，义旗空复指。","侯氏何多仁，慷慨同日死！","难弟亦捐躯，与子成连理。","为谢经术儒，通经固如此！"]},{"t":"哀江南 其十二","f":"五言古诗","c":["我闻章孝廉，罗源政不朽。","簿书终日烦，琴书尚在手。","去县三年馀，清风今满口。","里居自乘城，胡来通国走。","登陴者何人，一死誓所守！","端坐待兵加，临锋引颈受。","微躯许桑梓，吁嗟竟不负！"]},{"t":"哀江南 其十三","f":"五言古诗","c":["顾侯尹钱塘，才气素英果。","骄虏渡吴江，誓往邀其惰。","中丞已郊迎，欲袒谁当左！","妻孥笑指波，版籍泣投火。","两膝屈不得，踞向穷庐坐。","举幡士女号，请元门人裹。","拜舞迎阶墀，独行庶不颇！"]},{"t":"哀江南 其十四","f":"五言古诗","c":["孝廉素游侠，六艺兼文武。","楼船驻太湖，敌至骤风雨。","髵䰄满船头，羽箭大如柱。","壮哉葛孝廉，一呼双睛努。","手刃四、五人，群胡舌为吐。","力尽乃自刭，既殁有馀怒。","埋骨秋草中。","千年长不腐！"]},{"t":"哀江南 其十五","f":"五言古诗","c":["节义遍江东，皖人殊可丑。","岂知刘广文，临难竟不苟！","捧檄署泾县，胡来誓死守。","城破何从容，赴井还携妇。","又闻周广文，敢战敌为走。","仓卒殒学宫，绝命刃在手。","拔刃手不开，殉之庶无负。","如何泾县亡，一时有二叟！"]},{"t":"哀江南 其十六","f":"五言古诗","c":["麻生伟须眉，顾盼肃孤高。","身长七尺馀，意气为人豪。","置酒召宗族，誓不污腥臊。","宗族数千人，一一勇带刀。","宣城城尽闭，泾溪将屡逃。","势去身见俘，衣冠赴市曹。","绝命咏诗篇，慷慨色无挠。","有志竟不成，吁嗟命所遭！"]},{"t":"哀江南 其十七","f":"五言古诗","c":["吴王鸡坛雄，崛起树赤帜。","学术虽非淳，才气岸然异。","里人兴义兵，共推季子智。","攘臂事从戎，空拳当铁骑。","始愿岂捐躯，临危勇就义。","头颅姜竿悬，巾帻俨未坠！","生乎苦好名，一死庶无愧！"]},{"t":"哀江南 其十八","f":"五言古诗","c":["新安初不守，仗节司李独。","岂意衔须人，近出乌程族！","妻女手自屠，终焉一剑伏。","脰断不肯殊，抉吭以瞑目。","尸听府吏裹，义动酋长哭！","昔闻潘生言，凛焉毛发肃。","我歌江南哀，哀绝为君续。"]},{"t":"南京六君咏 其一","f":"五言律诗","c":["「不走」黄端伯，居然揖左贤。","忘生缘学佛，骂敌反称颠。","岂有头皮硬，还期心血溅！","帐前新辫发，可悔罪通天！"]},{"t":"南京六君咏 其二","f":"五言律诗","c":["回首钟山树，伤心计部书。","寝园闻渐废，宫殿早为墟。","即拟收京捷，还怜死国疏。","忠襄墓前柏，荣悴定何如！"]},{"t":"南京六君咏 其三","f":"五言律诗","c":["颇闻张吏部，不减邓攸贫。","海内存清节，朝端累党人。","死生翻易决，同异底难泯！","雪涕鄘城令，千言状正新。"]},{"t":"南京六君咏 其四","f":"五言律诗","c":["铮铮杨御史，阉党共推君。","「要典」三朝据，同流一死分。","漫嗟遮锦被，转恨杂鸡群！","可信髯司马，投降最早闻。"]},{"t":"南京六君咏 其五","f":"五言律诗","c":["传道城南乞，蓬头发正多。","羞他中国变，屡被市人呵。","入夜语还泣，沿街骂且歌。","沟渠绝粒死，此志是如何？"]},{"t":"南京六君咏 其六","f":"五言律诗","c":["痛哭桥边卒，临河羡独清。","世徼明主饩，肯荷敌人兵！","中国谁称帝，元勋竟献城！","可知徐久爵，尽室向燕行！"]},{"t":"望长沙","f":"古风","c":["汉、唐中兴誇将业，司徒仿佛尚父同。","我朝诸将何寂寞，海内独数长沙公。","长沙僻处湖南郡，能修甲兵控江东。","此公忠勇不世出，谋略似有鬼神通。","武昌跋扈劫不得，倒流七日浮波中。","扶持阴蒙上帝力，应知炎祚非遽终。","绿林青犊势淘淘，旌旗十万渡江红。","单骑驰壁拊其背，叩头请死愿输忠。","荆、樊铜马百馀万，闻声纳款来趋风。","连城带甲跨江、汉，胡儿不敢南弯弓。","貂蝉铁券灵武锡，屡请天仗临元戎。","迟回竟使至尊误，乘舆莫返咸阳宫！","只臂再扶汉社稷，整顿湖湘驭群雄。","野人讹传焉足信，捷书狎至耳欲聋。","或言楼船下章、贡，浔阳千里尽艨艟。","又言杉关传檄上游定，铁骑莽莽八闽空。","我闻豫章诸将久思汉，昔在门下受恩隆。","蜡书阴结理宜有，江右郡县岂待攻！","古来童谣有天意，望公早出成大功！"]},{"t":"忆龙眠 其一","f":"五言律诗","c":["龙眠君领袖，一第早飘零。","身命同磨蜴，诙谐本岁星。","姓名行屡变，医卜试偏灵。","菁峒穷栖处，哀吟谁与听！"]},{"t":"忆龙眠 其二","f":"五言律诗","c":["短檠孤咏夜，憔悴忆方干。","族大辞人熟，身羸苦夏寒。","诗书经乱废，车马隔篱看。","故里田荒尽，悲君去住难。"]},{"t":"忆龙眠 其三","f":"五言律诗","c":["零落山中伴，艰难乱后身。","交游连党祸，亡命困风尘！","慎勿惭名父，惟宜养寡亲。","三都孤馆夜，风雨共何人？"]},{"t":"忆龙眠 其四","f":"五言律诗","c":["十年同出处，乱后数偏奇。","作吏君先达，从龙我后时。","艰难千里共，心迹两人知。","扈跸挥毫夜，雄文更忆谁！"]},{"t":"忆龙眠 其五","f":"五言律诗","c":["难馀谁共事，对酒忆刘生。","祸以交亲累，名因与党成。","举家啼海岸，四壁阻江城。","念尔同门友，殷勤乱后情。"]},{"t":"永安舟次","f":"五言律诗","c":["兵起收群盗，溪边夜可行。","泊舟秋草市，卖酒旧瓜棚。","远寨传鸡唱，中流乱马声。","渡头灯火绝，孤月坐来生。"]},{"t":"莲子峒","f":"五言古诗","c":["蹻腾绿林雄，杀人何草草！","长技在掠夺，迅若疾风扫。","窟宅莲子峒，官军漏征讨。","今来张义旗，出入恣所扰。","得志倾巢来，卷地欲未饱。","已觉井邑空，转帐市廛小。","千队忽出城，沙飞城南道。","四郊无人居，田荒屋亦倒。","骨肉尽为俘，蹂躏何时了！","杀气瘦浮云，长戟阻飞鸟。","安得主帅明，散尔归田早！"]},{"t":"不合行","f":"七言古诗","c":["男儿不合生慨慷，皮骨欲尽项仅强。","游戏虎穴此危道，何苦锋刃相激昂！","万事转轴谁能料，褒衣大冠迂可笑。","昨日皂隶今乘舆，公然抗礼争容貌。","狺狺肝人盗蹠雄，堂堂杀气怪生风。","血肉淋漓罗几席，一言相失双睛红。","昨日语难瞋目久，霜刃霍霍掣在手。","从容理夺路人惊，鸡肋何心脱虎口！","归来返顾气转索，七尺相看何太薄！","男儿躯命有时轻，杆把隋珠浪抵鹊。"]},{"t":"哀哉行","f":"五言古诗","c":["沙县昔富盛，苦遭墨吏虐。","开门揖义兵，如何反驱掠！","银铛遍郊原，旌帜塞城郭。","谁怜富家儿，出门行带索。","富人何罪辜，累累马前缚！","大麦死沟塍，抱饥不得获。","贾贩乘朱幡，倡优充铃阁。","王侯递称尊，笙歌相间作。","戎马百田间，居者自云乐。","如彼鱼游鼎，如彼鳦巢幕。","欲谏反见嗤，哀哉泪潸落。"]},{"t":"戊子元旦","f":"七言律诗","c":["晓色荒荒氛祲浓，杉关何计一丸封！","半年常见双峰火，三户重销五夜烽。","城上乌啼稀击柝，帐中儿醉不闻钟。","残生敢问绸缪计，好去寻山趁短筇。"]},{"t":"元宵","f":"五言律诗","c":["闽海春三度，何年此夜晴。","孤灯然客恨，片雨入乡情！","野庙求神语，空山见火行。","病馀眠不著，泪满晓钟声！"]},{"t":"哀邵武","f":"五言古诗","c":["我行樵川道，十日无鸡声。","篱欹路亦断，麦死田未耕。","野雀噪虚灶，炊绝何由生！","有翁草间伏，见人如鸟惊。","屡唤不回首，恐是豫章兵。","豫章兵亦锐，主将亦有名。","今春大出师，曾一近郡城。","是时义声震，志在开门迎。","城外忽奔北，势溃无支撑。","可怜内附者，锋刃骈首婴！","攻城既失利，攻野肆搒掠。","居积既以尽，搜括罄瓶罂。","此岂主将过，或未纪律明。","嗟哉乌合众，约法安能行！"]},{"t":"翠云峰初度","f":"五言古诗","c":["兵过关路绝，穷栖僧刹古。","老树焚再生，岩花落更吐。","寂寥初度辰，廉纤经旬雨。","霏殿暗龛灯，侵廊哑信鼓。","稽首礼空王，我生是谁主？","今晨三十七，所历遍诸苦。","身名虽未亏，死丧竟何补！","幸际天日开，春王朔再睹。","从此得归欤，黄帽归净土。"]},{"t":"出黄土隘","f":"古风","c":["三年困闽峤，忧心一何癙！","周原骋戎骑，穷岩森义旅。","田芜畴以堙，村墟烟不举。","路逢饥饿人，惊走如窜鼠。","嵚?度闽隘，戈矛屡见阻。","虽怀糇?忧，寓目好禾黍。","时有妇人汲，或闻农父语。","且喜稻花扬，宁辞草根煮！","溪声荡烦襟，微飙散馀暑。","茅茨见夕阳，返顾慰徒侣。","今宵解带眠，斗酒不负汝！"]},{"t":"熊村被掠","f":"五言古诗","c":["出关吾意放，落日畏途偏。","岂有戴渊念，应无李涉贤！","风尘新白发，灯火旧青毡。","多难淹三载，为贫验一肩。","宦悲游子薄，装动健儿怜。","野寺寻鞍马，空山乱卷篇。","琴书留啸咏，枕被失安眠。","江路今如此，前程意惘然！"]},{"t":"江城感事 其一","f":"七言律诗","c":["章、贡双江梗不流，两勋旌节在虔州。","谓宜乘胜趋牛渚，何取攻坚顿虎头？","五岭闻风归正朔，孤城背日作边愁。","中兴时异承平计，误拟文成据上游！"]},{"t":"江城感事 其二","f":"七言律诗","c":["拂庐毡帐遍西山，杖钺登陴对垒间。","天马夜嘶流血汗，鬼神阴怒见嗔颜。","共传汉寿宣威久，又见杉关整旅还。","好驻两湖分犄角，漫提兵马聚城阛！"]},{"t":"江城感事 其三","f":"七言律诗","c":["滕王高阁迥含烽，巨堑长围定几重。","心向海天捞日月，手携风雨献蛟龙。","蜡丸再睹春王朔，铁券重颁大国封。","扈跸词臣谁草诏？","曾无涕泪洒兵农？"]},{"t":"江城感事 其四","f":"七言律诗","c":["羽檄星飞大将坛，江南、江北尽衣冠。","家家牛酒迟戎旆，往往毡裘盼汉官。","岂谓楼船消息断，重教村郭吏民残！","海门东去烟尘接，回首钟山掩泪看！"]},{"t":"曾吏部","f":"五言古诗","c":["临川昔多英，哲人迈时辈。","自挺冰雪操，不受床前诲。","毁室祭义旗，师少战士倍。","所悲国事非，宁惜身家碎！","天运一朝回，日月还昭代。","志士睹中兴，斯人独不逮！","畴昔关弓仇，至今抚膺悔！","来往公旧居，榛墟生感慨！"]},{"t":"建昌守","f":"五言古诗","c":["昔过三衢市，狼狈史司理。","为言旴城破，我走太守止。","缟衣者少年，云是太守子。","凶耗传未真，旁皇失坐起。","虽无涕泪悬，意色不忍视！","今闻旴人言，捐躯公素矢。","被缚入武昌，还闻骂贼死。","骸骨委江城，亲戚复谁恃！","不知缟衣儿，曾否负归里？"]},{"t":"新城令","f":"五言古诗","c":["旴江马初嘶，黎川火已彻。","将军昼闭垒，高宴欢未绝。","县令夜登陴，殉城志早决。","自言出关来，豫与家人诀。","敌来将已奔，城空令徒设。","矢受南八面，衣湔嵇绍血。","所祈民命全，甘靖小臣节！","朝廷未知名，里巷常呜咽。","或云梦为神，位与睢阳列。"]},{"t":"闻岭南信志喜","f":"七言古诗","c":["翠盖霓旌常在眼，三湘、百粤久无闻。","羽书快捧江西捷，露布惊传岭表文。","雾散庾关开汉月，风清瘴海失妖氛。","荆、湖义勇声全壮，章、贡孤穷力又分。","遂使桂林腾紫气，坐看端水捧黄云。","门前履错星辰客，帐下威生虎豹群。","身著戎衣迎御辇，手披仙仗拜明君。","金阶独对边机密，铁券频辞诏使勤。","处处农歌沽酒庆，家家官路瓣香焚。","早趋南浦烧攻具，直下金陵洗战裙。","雁塞烽消无斥堠，王庭犁罢尽耕耘。","中兴大写功臣貌，返正应推第一勋！"]},{"t":"读黄海岸先生「明夷集」","f":"五言古诗","c":["庞公学道处，庐峰孤月时。","赤脚发狂走，咄咄空中奇。","微言成怪诞，流俗骇愚痴。","妙谛岂足诠，大悟见临危。","敌来倾国迎，高遁贤者为。","不臣复不去，幽囚还赋诗。","白刃岂不利，强项不可施！","所由心坚刚，宁有鬼神持！","我读「明夷集」，激楚凄肝脾。","至人已形解，壮士空含悲！"]},{"t":"续哀 其一","f":"五言律诗","c":["三年两遇难，时势岂全非！","文物从今盛，坚贞自古稀。","几人辞马革，何处问乌衣？","血碧江南草，离离未可归！"]},{"t":"续哀 其二","f":"五言律诗","c":["节义云间盛，陈登志更悲。","九旬存大母，五世得孤儿！","意气同人尽，株连一死迟。","虏廷无血溅，长啸逐鸱夷。"]},{"t":"续哀 其三","f":"五言律诗","c":["惆怅阊门路，鸡林手泽新。","不容汉处士，宁禁宋遗民！","道在乱离见，交从钩党亲。","可知名义重，还是旧同人！"]},{"t":"续哀 其四","f":"五言律诗","c":["昔岁疁城破，君家死丧多。","此心终不改，天意欲如何！","道貌冰壶映，佳儿玉树罗。","一时摧折尽，回首剧悲歌！"]},{"t":"续哀 其五","f":"五言律诗","c":["抗节钱塘令，湔衣血尚红。","宁知三载后，又著一门忠！","阖室容张俭，谁人释孔融！","夜台应不恨，吾道泣何穷！"]},{"t":"续哀 其六","f":"五言律诗","c":["泉明闻又殒，不愧裹尸亲。","竟死忠臣绝，争传孝子真。","从容公就义，激烈尔成仁！","坐笑求生者，空劳涕泪频。"]},{"t":"续哀 其七","f":"五言律诗","c":["孺子渥洼种，早龄特好奇。","论年刑可免，取义死妨迟！","笑改夏侯色，羞称潘岳诗！","考功讵不祀，应有腹孤遗。"]},{"t":"续哀 其八","f":"五言律诗","c":["入暮刘公干，元戎奉指挥。","帐中机不密，海上约偏违！","祗怪人谋失，谁言天意非！","君看吴地败，江岭已全归。"]},{"t":"广哀 其一","f":"五言律诗","c":["将军兵未散，何事欲捐生！","尽室沈沧海，单车指旧京。","衣冠老父泣，意气敌人惊。","西市风沙起，天心正不平！"]},{"t":"广哀 其二","f":"五言律诗","c":["七十犹倡义，谁能惜此生！","莫悲赍志殁，原不望功成。","诗咏游仙乐，死传坐化名。","争知尸解去，底用哭真卿！"]},{"t":"广哀 其三","f":"五言律诗","c":["中丞初战死，祠庙宛陵新。","谁窃王綝首！","还完重捷身，藁竿无不可，合葬亦随人。","近说忠魂附，家家祀作神。"]},{"t":"广哀 其四","f":"五言律诗","c":["报国詹公子，麾兵战不还。","空传云雾险，竟死大安关！","马忆长干瘦，衣怀京兆斑。","西溪双血泪，洒滴遍闽山。"]},{"t":"广哀 其五","f":"五言律诗","c":["谁怜王录事，竟死婺州围！","抗节江东盛，殉城大吏稀！","坚持太守篆，还著幕僚绯。","一死南朝重，毋言职最微！"]},{"t":"广哀 其六","f":"五言律诗","c":["华亭多节义，死丧及师儒。","题壁留谁看，升堂笑独迂！","特书「明命永」，果兆汉兴符。","正朔鬼神奉，忠魂得慰无？"]},{"t":"广哀 其七","f":"五言律诗","c":["痴肠吴太学，国破早捐生！","莫听呼天诉，聊明报汉情。","鬼神应有恨，劫运恐难争！","近喜威灵见，南昌虏数惊。"]},{"t":"广哀 其八","f":"五言律诗","c":["抗节师儒事，坚贞似尔稀。","为纾雷泽难，竟著杲卿衣！","幽梦期当践，家书付未归。","三闾虚庙待，并祀志无违！"]},{"t":"广哀 其九","f":"五言律诗","c":["吾乡吴季子，猿臂喜弯弓。","空有捐家志，莫抒报国忠！","泪沾三诏湿，梦拟七闽通。","莫笑龙眠弱，孙、吴算两雄！"]},{"t":"广哀 其十","f":"五言律诗","c":["戴渊起陈墓，事败竟降胡。","谁信李陵志，真成伯约图！","汝惟拚一死，天欲祸三吴。","地下精灵聚，犹为厉鬼无？"]},{"t":"广哀 其十一","f":"五言律诗","c":["举国争披发，危冠尔独悲。","鱼虾皆马革，天地一鸱夷！","节义乡邦讳，姓名估客知。","会稽江上水，千里接鸠兹。"]},{"t":"广哀 其十二","f":"五言律诗","c":["留都兵散日，节帅几人亡！","祗怪南朝弱，犹怜蜀将强！","江山千载恨，清白一门香。","拟作招魂赋，遥投北固旁。"]},{"t":"广昌访刘广生孝廉","f":"七言律诗","c":["木落西风客到迟，荒村才过乱离时。","几家蓬径初除草，是处柴门新补篱。","杨柳条抽烧后树，芙蓉花发折残枝。","琅琅石户经声远，破案焚香诵「楚辞」！"]},{"t":"闻驾跸端州，喜赋","f":"七言律诗","c":["黄星三岁望中迷，唐突烽烟信马蹄。","祗听诏书传桂水，果然辇跸驻端溪。","欢腾义士添朝勇，魂慰孤臣罢夜啼。","此日中原思汉极，六龙早出大江西！"]},{"t":"晤曾庭闻，卸熊子文给谏死难汀州","f":"古风","c":["并舫双江夜雨吹，疏灯坐对虎头痴。","人前屡发怀沙愿，酒后哀吟吴帝诗。","鸣?趋朝班已散，当门噀血骂谁知！","双峰古署衔杯话。","竟是荆卿死别时！"]},{"t":"得刘客生信","f":"七言律诗","c":["别君荒署露华凝，寒月清樽涕不胜！","长虑一杯成永诀，可怜万死见中兴！","玉关岂料生能入，仙阙唯馀我未升！","多少故人麟阁上，如卿兄弟最先登。"]},{"t":"虔州死节歌","f":"七言古诗","c":["虔州城破相公亡，矢石既绝参犹张。","跃马夺门锋莫当，回鞭赴水何慨慷！","太宰清忠海内望，投缳仓卒正冠裳！","司马有志不得将，出城欲去中彷徨，翻然裹帻殉封疆。","彭公靖节意久藏，匕首毒药左右防，郁孤台上此志偿。","御史一死扶纲常，从容绝命圣人堂。","别驾潇洒酒中狂，临危不屈项果强。","虬髯铁面周职方，嚼齿骂贼肉飞扬。","卢君里居须眉苍，倚杖妻儿次第僵，终焉清冷完幽芳！"]},{"t":"崇化村遇虔人，云以丙戌十月过韶州见小儿于二刘舟中","f":"七言律诗","c":["失尔经今三易秋，三年有客见韶州。","依刘旧恃通家谊，过岭遥纾大宅忧。","迹足可怜随万里，吞声何处哭孤舟！","崎岖念汝心全折，舐犊情痴雪满头！"]},{"t":"初度岭，与张太羹谈虔州事","f":"七言律诗","c":["虔州自是咽喉地，天下讴吟金与王。","受困五月围不解，援师只盼岭南强。","我闻章、贡颇负固，坚壁清野还赢粮。","疑兵缀之肘可掣，且出间道趋南昌！"]},{"t":"喜闻吴鉴在御史持斧粤西","f":"七言律诗","c":["艰难逐伴向南天，铜柱霜威度岭传。","鬓发可怜庾信老，勋名已让祖生先！","嗟予虎穴潜踪日，正尔骢车揽辔年。","霄汉有君吾且逸，好依柏府纵高眠。"]},{"t":"喜达行在二十韵","f":"五言古诗","c":["异域疑终老，生归吾岂望！","谁怜灰劫后，重见曜灵光！","祗讶魂超越，犹愁梦渺茫。","饥寒来北海，涕泪睹南阳。","日出明宫阙，云低抱苑墙。","朝廷遂礼乐，我辈竟冠裳！","诸将鸣鞭锐，千官佩玉锵。","避车多豸绣，骑马有貂珰。","访旧勋俱大，逢儿我并长！","去珠还入掌，断雁再随行。","趋陛肘时露，陈书指欲僵。","故人相问讯，童仆转凄凉！","发向僧居保，颜从虎穴苍。","赖将诗过日，但忆笋堪肠。","濯足通身暖，寻医百节伤。","屩穿知步履，肩袒验刀疮。","已慰玉关愿，宁劳属国偿！","解装存笔砚，纪事足篇章。","钓艇三人酒，茅庵一月粮。","此生依辇跸，歌咏六龙傍。"]},{"t":"到端州得儿法祖志慰 其一","f":"五言律诗","c":["三年啼已罢，万里尔犹存。","把袖天涯梦，伤弓闽海魂！","语音乡国变，长大故人恩。","欢剧嗟苏武，还家乏子孙！"]},{"t":"到端州得儿法祖志慰 其二","f":"五言律诗","c":["丧乱今逢汝，艰难望尔贤！","毋烦谋鹤俸，便欲买渔船。","避难须贫贱，佣生只卷篇。","有儿扶几杖，恣意老江天！"]},{"t":"寄呈留守瞿相公 其一","f":"七言律诗","c":["稽首虞山拜相公，汉廷勋业许谁同！","自擒宗孽人心定，再整危疆将略雄。","屡降白麻趣秉政，终拚黄发老从戎。","祗今鹓鹭归仙仗，争念麒麟第一功！"]},{"t":"寄呈留守瞿相公 其二","f":"七言律诗","c":["中兴根本仗谁留，楚、粤经年次第收。","羊祜在军常缓带，庾公乘月亦登楼。","幂中书记欺韩愈，帐下诸儿问许侯。","近喜湖南何相国，时从枕上借边筹！"]},{"t":"寄呈留守瞿相公 其三","f":"七言律诗","c":["铁券新辞五等勋，可堪时事又纷纭。","荆南捷奏经时至，江右援书迥未闻！","图籍应归萧相国，功名独让李将军。","即今政本还虚席，诏使频催下五云。"]},{"t":"寄呈留守瞿相公 其四","f":"七言律诗","c":["辛苦延津事已非，生还辇下愿多违！","苏卿有节谁人验，王粲无家何处归？","喜听蛮方歌赤舄，争传词客满黄扉！","袖中双笔犹堪用，拟向公门马上挥！"]},{"t":"全阳松，和留守相公韵 其一","f":"七言律诗","c":["全阳官路万株松，蔽芾千年不受封。","为驻元戎休汗马，遥瞻大旆杂交龙。","阴森夹道风堪御，屈曲临关幰不容。","见说相公曾揽辔，自云常护至今浓。"]},{"t":"全阳松，和留守相公韵 其二","f":"七言律诗","c":["谢公即事有篇章，况是褰帷乍得凉！","万骑迎风辞洒濯，千官解带共徜徉。","诗成马上烟尘净，客到车前翰墨香。","非是见松幽意惬，老臣同尔傲冰霜！"]},{"t":"全阳松，和留守相公韵 其三","f":"七言律诗","c":["天南捧日再兴年，草木公然戴汉天。","弘景爱声空忆隐，留侯作伴漫求仙。","道旁早勒停车石，林下应添饮马泉。","莫拟相公心暂息，轻摇羽扇正筹边。"]},{"t":"全阳松，和留守相公韵 其四","f":"七言律诗","c":["此地新经虎豹过，更冲炎暑去如何！","烽销喜见栖玄鹤，泉闭嫌曾饮橐驼。","侧耳寒涛疑泛海，沾衣空翠笑扪萝。","几经劫火阴常在，为荷先朝雨露多。"]},{"t":"酬汪辰初","f":"五言律诗","c":["三年沦异域，一命重同官。","以我栖山苦，羡君渡海安！","图书随宦失，生死诉人难。","近奉新功令，休称两鬓完！"]},{"t":"哭费司理死难雷州","f":"五言律诗","c":["海南城破日，殉难独雷州。","大节同时抗，孤忠一死优！","铅山家早破，蛮郡骨谁收？","知己恩难负，如君志已酬！"]},{"t":"虔州续歌","f":"七言古诗","c":["虔州陷后死者多，给谏不死意如何？","舁去南昌还绝粒，不死锋刃死沈痾！","睢阳激烈气诚壮，偃师需缓志岂颇！","南海职方援兵至，入城不出今则那！","吏部绝命无人见，城内谁能逃网罗！","吾乡亦有胡通守，举家煨烬同消磨！","其馀流寓复谁在？","出城尽葬江心波。","玉石俱焚无足道，纷纷请恤殊淆讹。","古来节义凭信史，敬采里巷成续歌。"]},{"t":"髯绝篇。听司空耿伯良叙述，诗以纪之","f":"五言古诗","c":["髯昔东奔婺，本恃同官情。","婺州方举义，朱公建戎旌。","要髯共整旅，遂抗同官衡。","同官为隐忍，义军为不平。","护之还江上，因入方帅营。","马相久在幕，后至权稍轻。","计邀方帅欢，二竖还相争。","郁郁怀异志，遣谍潜归诚。","是时越守固，降表达燕京。","阴以国情输，还令虏增兵。","六月虏渡江，长跪江头迎。","贝勒久始信，涿州书乃呈。","叩头感且泣，誓死报圣清。","招降方与马，踊跃随长征。","自请五十骑，先克金华城。","跃马到城下，长啸颩胡缨。","昔闻朱公计，城西角易倾。","此来直攻瑕，炮火蹋天轰。","须臾城西陷，戮及怀中婴！","耿君亦被系，望髯气正英。","贝勒酬髯官，悬称内院荣。","次第度闽峤，所过无草茎。","群酋罕肉食，髯至必大烹。","相顾笑且骇，每夜盘飧盈。","作歌劝酋酒，群酋饮必酲。","争言梨园伎，南来耳髯名。","髯起顿足唱，髣髴昔家伶。","有酋求学诗，唱和到五更。","晨起历诸帐，每谈必纵横。","一朝面目肿，群酋人人惊。","托耿往语髯，且缓闽中程。","髯老而过劳，即防疾病撄。","髯闻大忧疑，疑有阻其行。","『酬官谅不欺，此意胡然萌？","我年甫六十，有如铁铮铮。","实无秋毫疾，愿君为我明』！","耿君还复命，群酋指胸盟。","急邀并马走，仙霞岭峥嵘。","群酋皆按辔，惟髯弃马行。","健步奔犊捷，矍铄聊自鸣。","上岭复下岭，顾笑群儿狞。","急踞磐石坐，呼之目已瞪。","马棰掣其辫，气绝不复生！","群酋齐下马，环哭为失声。","亟命索火炬，荼毗藏诸罂。","家僮搏显泣，请还附先茔。","方、马随入关，尸首委长鲸。","惟髯有遭遇，所志惜不成！","耿君新返正，列为行在卿。","始末亲所见，记以待史评。"]},{"t":"俞生行","f":"古风","c":["中丞军败为虏获，绝粒不死重思活。","左右相随只两僮，西市放回系狱中。","狱有仆夫玉卿者，欲窜中丞无与同。","闽人俞生雅好义，阴为玉卿画奇计。","部署略定告中丞，转令中丞心胆悸。","为说累臣病不痊，两僮偷伴狱官眠。","乘夜出狱傍城宿，诘朝早上俞生船。","狱官晨问中丞恙，双履榻前宛相向。","呼僮迎医僮不行，彼此相推齐出城。","俞生船开去如箭，两僮出城盼不见。","下江兵阻转柁回，扑面差池争一线。","舍船得岸望西驰，日中才闻兵马追。","夜奔间道虎口脱，扳翻荆棘无完肌。","奔波力尽一僮死，中丞谒驾诉天子。","俞生面受别驾恩，馀人供作军功纪。","鄞江一夜胡尘飞，中丞兄弟突重围。","同来义士复散失，应向故乡觅路归。","国运重兴有天意，百官扈跸随时至。","俞生皂帽翩然来，邓僮趋跄称小吏。","更闻狱官受累犹未诛，株连同类死复苏。","江右返正皆赦罪，上书乞恩两人俱。","中丞者谁司寇是，得书忆旧悲且喜。","特疏为叙狱官冤，两人并奉超迁旨。","诸君义重报亦殊，独有玉卿消息无。","君不见小吏骑马得官职，别驾循资升大夫？"]},{"t":"得方密之信见寄","f":"七言律诗","c":["同时亡命五经春，岭峤分飞痛甲申。","夜卧惊啼频梦虎，朝行掩面怕逢人！","佣书海市音全变，卖药山城术已神。","闻道徵车求旧切，漫藏名姓更垂纶。"]},{"t":"酬金给谏卫公","f":"七言律诗","c":["峒户蛮村老此身，直声猛气动延津。","重来琐闼风裁旧，独对青蒲袖草新。","多难朝廷容敢谏，中兴将帅重清贫。","金章铁券休轻觑，抗疏当关正有人！"]},{"t":"密之与鉴在相依桂水，贻书招予。书怀二十八韵奉答","f":"五言古诗","c":["方朔金门彦，延陵直指声。","艰难猺峒路，遭际桂林城。","书到知予在，歌长见友情。","离群真历劫，访旧半构兵。","党锢同亡命，髡钳各易名。","故人皆散失，季子得逢迎。","卖药方曾效，从戎计未成。","吴江家总破，闽海国重倾！","癙泣通三载，夷歌尽五更。","葵心终耿耿，蒜发故茎茎。","崖复看猿度，天长羡鸟征。","梦颠江右复，涕洒粤东平。","过岭风全暖，开年日迥明。","朝廷需战伐，吾道愧坚贞！","再著冠裳好，重逢父子惊！","鸡坛皆列宿，麟阁半同盟。","学士今为相，台郎且晋卿。","携孥依北道，给札赋西京。","对酒探阄熟，联吟并马行。","双星随斗出，一雁掠霜鸣。","祗觉生存幸，翻悲死丧轻！","武公尸不返，农父祸谁撄！","白社馀三士，青云仗两兄。","服官怜我拙，招隐鉴君诚！","水忆漓江碧，峰思独秀晴。","躯残舌仍在，粒绝笔能耕。","岁月将诗记，篇章把烛评。","春帆应抚手，唱和送馀生！"]},{"t":"送吴青闻给谏解官西上","f":"七言律诗","c":["炉烟初散解朝衣，白舫苍梧去不违。","抗疏未蒙明主放，避谗先许直臣归！","忧时计笑书生过，去国人怜谏草稀！","似我合随梅尉隐，伏波山下订渔矶。"]},{"t":"酬袭在田孝廉","f":"七言律诗","c":["沙县惊逢断雁行，乱离相抱共存亡。","先公旅榇淹蛮土，令弟麻衣带贼伤！","左衽最怜吴地客，南冠犹恋汉家装。","幸逢正统宁宜去，且辍忧时痛哭章！"]},{"t":"赠丁掌垣","f":"七言律诗","c":["忆昨联樯章水上，三年仙籞再经过。","朝因卧病晨趋少，疏为忧时夜草多。","补衮即看新领袖，摇金还听旧鸣呵！","青蒲第一边机急，莫向樽前纵啸歌！"]},{"t":"赠李源白金吾","f":"七言律诗","c":["汉家天子报功殊，沈弇同时列画图。","仙仗晓趋扶玉辇，羽书夜到召金吾。","閒教侍史亲调管，醉看孤儿健挽弧。","骑马天街人肃肃，露章霜色满行都。"]},{"t":"麻河捷","f":"古风","c":["中兴马侯古精忠，天子论勋册上公。","毛生夜述麻河战，满堂骨竦生英风。","是日初战兵不利，虏骑骁腾万马雄。","将军下令尽弃马，短刀秃袄来争功。","麻河岸高敌初驻，栏楯层层壁垒固。","汗马解鞍兵作炊，我兵突至谁能禦！","可怜攻壁壁不开，壁门炮火轰如雷。","将军大呼身先进，人人死战坚为摧。","壁门既夺虏营乱，黄昏截杀及夜半。","铁骑嘶颤橐驰奔，全军逼水容谁窜！","天风吹月月朦胧，照见虏营营已空。","僵尸枕藉安足计，馀者尽葬麻河中。","拂庐万落三军宿，胡妇琵琶唱胡曲。","将军举酒健儿歌，残魂何处吞声哭！","将军破贼檄屡传，岂似今无匹马还。","积弱屡朝初吐气，昆阳、钜鹿谁争先！","我闻桂林虏来举城走，瞿相从容袖两手。","焦侯三箭殪三骑，城门重闭至今守。","又闻西有滇帅胡将军，摧锋陷阵虏中闻。","身经百战锐不挫，南人争推第一勋。","诸将纷纷膺国号，因时窃位何足道！","马侯封公两人侯，此爵朝廷庶不冒！"]},{"t":"献玉篇","f":"七言古诗","c":["端州城中驻黄屋，南海士人献双玉。","上言得自南海旁，渔人海上夜见光。","明晨网鱼鱼眼动，剖鱼得玉如玺方。","是时天子新御极，玉献满朝动颜色。","诏出此玉付玉工，琢成纽鼻蟠蛟龙。","篆作皇帝受命宝，髣髴传国玺与同。","我闻此玺秦世造，当时刀笔何精妙。","胡主驮入沙漠亡，亡国物存安足道！","帝王应运非偶然，中兴必有符瑞先。","玺亡沙漠胡运尽，玉呈南海天意旋。","小臣且收卞和泪，抃手恭陈献玉篇。"]},{"t":"端州杂诗 其一","f":"七言律诗","c":["去年此日困胡尘，望阙心惊异域人。","死去可怜馀马革，生还何意识龙鳞！","天时过岭常疑夏，官署无花漫号春。","冠盖纷纷游宦乐，山川满目总伤神！"]},{"t":"端州杂诗 其二","f":"七言律诗","c":["庾岭军书昼夜飞，南昌无计解重围。","孤城烽锁粮垂尽，间道人疏信渐稀！","入对漫图方略上，请师空见节旄归！","同谋反正功休叙，可识章门事日非！"]},{"t":"端州杂诗 其三","f":"七言律诗","c":["辇卫萧条国计虚，元勋迎驾意何如？","度支空佩司农印，按部真埋御史车。","吏职滥从军府署，人情求仕汉廷疏。","阃权不肯兼中外，犹许朝班得内除。"]},{"t":"端州杂诗 其四","f":"七言律诗","c":["江右安危久不传，诸君高会庆新年！","未知南粤将军贵，祗讶西园公子贤。","卿士几人能入幕，朝廷何事可分权？","东来相国休凭藉，激切弹文出散员。"]},{"t":"端州杂诗 其五","f":"七言律诗","c":["回首神京直北看，天隅数郡岂偏安！","比闻政府频虚席，何事言官辄免冠？","国法未严臣节见，朝廷多故圣恩宽。","即今典制遵神祖，窃恐拘文此日难！"]},{"t":"端州杂诗 其六","f":"七言律诗","c":["近日中书诏已繁，词头更亵白麻尊。","本朝相业惟调旨，寰海人心仰代言。","天语简来偏足贵，温纶滥得岂为恩！","莫因乱世多宽假，一字低昂国体存！"]},{"t":"端州杂诗 其七","f":"七言律诗","c":["圣度遥从仗外瞻，天颜春蔼正尊严。","中兴政赖言官直，跋扈情销相国廉。","最喜文华勤讲幄，早传慈寿罢垂帘。","瞿公念主箴规切，握扇书成也不嫌。"]},{"t":"端州杂诗 其八","f":"七言律诗","c":["主恩浩荡等閒叨，谬厕儒冠拜赭袍。","藩吏几人瞻北阙，朝班此日重西曹。","乘时反正功非细，破格酬勋爵太高。","发鬓莫矜臣节苦，苏卿雪窖总徒劳！"]},{"t":"端州杂诗 其九","f":"七言律诗","c":["忠贞部曲驻施州，跃马争衡堵相谋。","江上势方成破竹，穴中斗忽起诸侯！","三年百战城全弃，五路连营兵已收。","湖北、湖南皆赤地，苍梧、象郡迥生愁！"]},{"t":"端州杂诗 其十","f":"七言律诗","c":["堵公亦是济艰材，曾抚荆南万马回。","心恃旧恩兵可用，疑生诸将志先灰！","檄援江右无时去，围困长沙竟不开！","试听楚人中夜泣，招魂千里为谁哀！"]},{"t":"端州杂诗 其十一","f":"七言律诗","c":["李公雅负中兴略，再出庾关功未成。","猛气岂徒援与国，锐师何故挫坚城？","降书狎至谋难测，战鼓相闻敌莫经！","整暇不教防燕饮，底须沈醉虐儒生！"]},{"t":"端州杂诗 其十二","f":"七言律诗","c":["乍丧元戎举国悲，军中留后早相推。","即愁阃帅权旁落，岂虑天王政下移！","诸将比肩轻节钺，同官属目拥旌麾。","纷纷割据知难问，从此关门不用师！"]},{"t":"端州杂诗 其十三","f":"七言律诗","c":["春王朔未出关门，喜见滇南使叩阍。","请附心知天命在，乞封名仰圣朝尊！","汉家故事须廷议，明主权宜有特恩。","史记功臣多赐姓，何难破例与称藩！"]},{"t":"端州杂诗 其十四","f":"七言律诗","c":["故人须鬓已非初，忧国图君志未舒。","名动宫庭宜早避，官兼清要岂长居！","也知宦热心原冷，莫使交亲迹渐疏！","同是布衣君最遇，从容膴仕意何如？"]},{"t":"端州杂诗又十一首 其一","f":"七言律诗","c":["给事趋朝袖草雄，更生笔削果虚公。","金吾奉主宜无过，中尉从龙信有功！","多难未须增水火，一隅底用判西东！","向来本触元勋忌，岂谓元勋志与同！"]},{"t":"端州杂诗又十一首 其二","f":"七言律诗","c":["相公再出辅吾君，捧诏趋朝亦太勤。","老子未惭「长乐」号，大夫难悔美新文！","露章谏议先时去，抗疏班行迥不闻。","风节最称金给事，依违也畏李将军。"]},{"t":"端州杂诗又十一首 其三","f":"七言律诗","c":["霜严宪府凛难攀，大谏风裁更领班。","便殿连朝求召对，敕书昨夜又封还。","朝廷纵小名犹在，方镇徒强主未孱。","底事髯公辞太戆，五千铁骑动龙颜！"]},{"t":"端州杂诗又十一首 其四","f":"七言律诗","c":["元戎杖钺已专征，约法南人禁举兵。","乌合自难迎大敌，骁腾或可借虚声。","冒封恩滥诛非罪，奉使官多撤有名。","过岭尚书旌节弃，幸邀铜马脱馀生！"]},{"t":"端州杂诗又十一首 其五","f":"七言律诗","c":["浔州节帅最卑庸，遭际同膺大国封。","坐拥旌旄凭跋扈，檄徵兵马正从容。","中朝名爵真疑滥，蛮地徵求岂胜供！","柳庆抚军新遇害，司刑无计问渠凶！"]},{"t":"端州杂诗又十一首 其六","f":"七言律诗","c":["中丞本意领中枢，诏抚忠贞拜命趋。","祗虑兵烽穷岭峤，何图使节丧萑苻！","驰驱未遂还朝志，沟渎轻捐报主躯！","纵使宦途多异议，无端阴计岂宜诬！"]},{"t":"端州杂诗又十一首 其七","f":"七言律诗","c":["圣朝新政惜繁缨，主爵升沈迥未平！","大抵远人宜重赏，纵然高位亦虚名。","雄谈竟博乌台贵，黠竖能邀回寺清。","独忆润州钱叔子，空穿芒屩粤中行！"]},{"t":"端州杂诗又十一首 其八","f":"七言律诗","c":["谏垣疏上争资格，阙下喧腾拥玉珂。","郎署有才能对策，圣朝无地可开科。","旧僚废籍徵皆遍，新进高班佔已多。","也识帝心偏爱惜，榜中人尽可如何！"]},{"t":"端州杂诗又十一首 其九","f":"七言律诗","c":["荣名虚冒乱离间，变后除书尽可删！","宫尹滥凭供俸窃，新恩屈就侍郎班。","为要使节频颁诏，漫假旌麾岂出关！","江右诸君承宠遍，故乡可听锦衣还？"]},{"t":"端州杂诗又十一首 其十","f":"七言律诗","c":["堵相临边未建勋，梧州矫诏册滇云。","便宜本自朝廷赐，封事无难咫尺闻。","谋启贼臣凭假借，使烦属国重纷纭！","即今庙议何时决，圣主殷忧孰与分？"]},{"t":"端州杂诗又十一首 其十一","f":"七言律诗","c":["督师失势在苍梧，败后犹防列镇图。","赤地魂销千里恨，沧江客散一舟孤！","戎机误国休轻诋，使相还朝岂易趋！","莫怪言官封事激，中湘遗恸满天隅！"]},{"t":"送毛恭则出监鄂国军","f":"七言律诗","c":["敕书使节下青霄，揽辔春城驿路遥。","帝念元戎勤借箸，诏加司马早辞朝。","楚疆戎伏毋忘备，鄂国功高未许骄！","克敌安民真将略，耕桑千里待君招！"]},{"t":"悲湘潭","f":"古风","c":["长沙兵散湖南空，湘潭城中失相公。","举朝变色摧天柱，白日惨澹黯行宫。","往时百战不足论，即今还弃垂成功！","可怜公长才五尺，头童齿豁一老翁！","铜马百万哮豺虎，仰公乳哺婴儿同。","时危饷诎谁用命？","赤手空口驱群雄。","湖南、湖北竟千里，卷云扫雾随天风。","祗期长沙不日得，游鱼命在沸釜中。","堵公心劳计转误，忠贞兵来互疑惧。","常德焚烧宝庆走，诸将旌旗挽谁住！","长沙城坏无人登，穷寇将奔守复固。","我兵溃走任东西，相公独在湘潭驻。","夜半衔枚虏骑来，湘潭无兵城门开。","相公衣冠虏能识，拥去罗拜声如雷。","大骂不绝相公死，但见长沙城中人举哀。","功名事业长已矣，忠臣义士胡为哉！","君不见忠贞兵过苍梧界，堵公双旌导马回？"]},{"t":"悲信丰","f":"古风","c":["信丰城外虏来急，将军勒马城上立。","黄昏对酒坐城楼，诸将言事那敢入！","酒酣掣剑剑不鸣，麾下去尽无人声。","夜半斩关诸将走，谁扶将军上马行！","城外水深雨如注，将军马小不得渡。","马声渐没将星沈，亲吏相随谁相顾！","偏裨左右尽归来，独少将军匹马回。","关门昼闭烽堠绝，天子震悼举朝哀。","语君且勿哀，军中收得将军印，元帅牙门昨已开。"]},{"t":"悲南昌","f":"古风","c":["信丰城败惠国亡，胡马东来势颇张。","白旗八杆章门至，始闻正月失南昌。","南昌将军谙戎机，婴城坐守听虏围。","闾阎万户人食尽，坑堑百道鸟难飞。","敌饱城饥夜深陷，将军上马犹酣战。","金公赴水气如生，王侯刎首色不变！","江人莫怪无援师，纵有援师来亦迟。","两勋收兵自不出，客兵云集来何为！","去年攻虔祗自弊，今来守城堕虏计。","又闻倡义非同谋，到死相疑还相制！","古言两雄不并栖，何不分兵犄角湖东、西？","何为一城坐困与俱毙，使我百姓无故成鲸鲵？","旧岁此城初反正，即今城破复谁恨！","英雄成败古来多，其奈城中人命何！"]},{"t":"端溪石砚歌","f":"七言古诗","c":["端州有石色皆紫，端州紫石砚盈市。","入市买砚苦不佳，佳者旧坑今在水。","前者尚书来搜坑，发兵障溪涸溪底。","溪水玲珑赴岩深，此坑宛在深岩里。","泅人没水舟然灰，腰斧穿岩及坑止。","坑中扪石截如泥，精粗不辨谁者是。","回身攀舷向灰掷，石被风僵兼火炙。","琢出犹存火衲文，最佳乃是蕉叶白。","点石取名献尚书，泅人出水浑搜索。","即今尚书一门屠，壮士磨刀复谁惜！","我闻此言自叹息，浪说鸲鹆眼能碧。","我有歙砚亦非真，笔锋扫秃何曾释。","只道端州砚易寻，那知满市屏风石！","归来洗砚还著书，此砚虽粗书盈尺。"]},{"t":"寄开少","f":"五言律诗","c":["间道延津出，生还意惘然！","雁行寻万里，虎穴足三年。","公道朝端少，威名蜀吏传。","惠连经岁至，芒屩竟空穿！"]},{"t":"送刘通候返黔，寄乃叔晋仲刺史都匀","f":"五言律诗","c":["故人天末宦，异地得通家。","草入郎官舍，山深刺史车。","庞眉烟际锁，双鬓瘴边华。","西送阿咸路，相思蛮树遮！"]},{"t":"刘同庵司寇自羊城回","f":"五言律诗","c":["亚卿衔诏日，留后建牙时。","国体宁毋失，军情且不疑。","盈廷人坐论，有事尔奔驰。","莫更陈辛苦，贤劳念者谁！"]},{"t":"送姚翁默仙入平西山中，寄曼公","f":"五言律诗","c":["尚有故人恋，胡为更远寻！","滩流当夏恶，瘴气入西深。","采药蛮中兴，钞方学士心。","逃虚执已久，应喜得跫音！"]},{"t":"刘客生詹尹直经筵讲官","f":"五言律诗","c":["詹尹辞风宪，承恩备讲员。","名因元老重，帝识布衣贤。","向北声容正，同官宴赏偏。","莫徒遵故事，政本是经筵！"]},{"t":"送别宪幕林树本之桂林","f":"七言律诗","c":["薄宦天南幸比邻，送君西去黯伤神！","趋朝有诏敦元老，抗疏分班出小臣。","政本岂应容失节，幕僚借此欲抽身。","桂林留守招贤地，扼腕同心大有人！"]},{"t":"同曹素臣入羊城纪事","f":"七言律诗","c":["崧台历岁任沈浮，老友邀同羊石游。","牡蛎墙高知近市，荔枝阴合一维舟。","驾风海舶来东岛，入夜蛮商遍酒搂。","古寺最多官最冷，与君耐可度清秋。"]},{"t":"过三水驿即事有感","f":"七言律诗","c":["三水城南野草衰，昔年此地斗王师。","可怜铁骑长驱日，正是戈船苦战时！","驿吏夜闻摩剑战，海天阴见列旌旗。","中丞、刺史同舟死，不死胡尘死更悲！"]},{"t":"广州杂诗 其一","f":"七言律诗","c":["上将輀回震海隅，追封「宁夏」宠谁逾！","藩王庆吊朝仪定，郡吏逢迎礼数殊。","鬼马烟销遗宝镫，佳人火化著珠襦。","共惊使客郎官贱，出入偏从甬道趋。"]},{"t":"广州杂诗 其二","f":"七言律诗","c":["红旗影飐角声喧，南海牙高留后尊。","秋至将骄谁出岭，日高人沸一开门。","有司心厌王官贱，除吏书愁幕府烦。","莫怪总戎难节制，将军原未识君恩！"]},{"t":"广州杂诗 其三","f":"七言律诗","c":["宝丰出镇许分疆，祖饯幢麾拥道长。","鬻爵颇疑藩吏贱，输钱为助岭军装。","悬知节钺轻难制，即恐关门弃不防！","巡海归来薛刺史，量移同去色凄凉！"]},{"t":"广州杂诗 其四","f":"七言律诗","c":["岭南财赋罄徵求，使者还劳费括搜。","仗节仍称周内史，鬻钱祗给粤诸侯。","门前桃李谁为主，海底珊瑚已尽收。","骑马健儿能荐士，上供曾否到端州？"]},{"t":"广州杂诗 其五","f":"七言律诗","c":["使客投閒卧海滨，轓车相过半交亲。","故乡归去衣皆绣，南粤游回橐不贫。","受职莫忘明主赐，衔恩况是历朝身！","汉廷吏道兼文武，岂畏兜鍪势逼人！"]},{"t":"吊忠诗 其一","f":"七言律诗","c":["寸磔常山痛未休，当时成败总难谋！","出师不战身空死，报国无能志已酬。","事转遗孤犹畏害，尸分列郡岂全收！","岭南反正渠凶戮，底事忠臣尚有雠。"]},{"t":"吊忠诗 其二","f":"七言律诗","c":["骂贼都门太史雄，书生殉国勇从戎。","南兵乌合知无济，西幸安驱正有功。","肘腋奸阴为间谍，头颅虏亦识孤忠。","谁言君父难同报，已博侯封晋乃公。"]},{"t":"吊忠诗 其三","f":"七言律诗","c":["端水龙兴此抗衡，两贤竟死粤东城。","但知正统人心属，岂料同舟颈血争！","汉祚未衰臣有节，国家多难尔成名。","即今逆命终身废，报汝当年面折情。"]},{"t":"吊忠诗 其四","f":"七言律诗","c":["苏公特达有思文，变后重图拥戴勋。","天命未知归圣主，国恩浪说报先君。","危时节劲身能死，正统辞严义不闻。","空使海南多杀士，至今此案尚纷纭。"]},{"t":"吊忠诗 其五","f":"七言律诗","c":["乱来死事几人传，霍氏幽芳最可怜。","閤户相扶争就义，沈渊取次未容先！","朝廷渐向天隅小，气节惊闻岭外偏！","殁后姓名少识者，老僧说罢泪潸然。"]},{"t":"书所闻","f":"七言律诗","c":["杨帅风闻已就刑，天隅此日识朝廷。","汉家有法宜明正，都尉阴谋似不经！","诸将强梁谋益狡，异时仓卒诏谁听？","南阳问罪功非细，即恐萧墙祸未宁！"]},{"t":"饮侯商丘舟中，即席赋赠","f":"古风","c":["我闻武岗帅叛城不守，天王西幸百官走。","天阴道滑两淋铃，乘舆狼狈古泥口。","尚方服物诏追随，纷纷相失竟何有！","侯生老将卧山中，锦衣御幄一时供。","盘羞珍进大官美，宫女香薰绣被浓。","卫士、中珰争醉饱，龙车凤辇去从容。","三宫娱悦天心喜，面承恩进「商丘」封。","侯生魁梧古良将，簪缨伟顾西班上。","有时对客一挥毫，集贤学士敛手让。","悲歌旧是梁园风，轰饮谁敌陈遵量。","翠釜金盘罗几筵，腐儒薄宦生惆怅。","朝传给事弹文雄，为褫滥爵核军功。","侯生罢酒颜色动，窃恐比例还同众。","侯生饮酒君勿疑，君之劳绩天子知。","即今军功期报主，报主孰有如君奇！","与君放船海珠寺，醉后且吟望海诗。"]},{"t":"别羊城","f":"七言律诗","c":["朝承书讯故人移，为报临轩试有期。","去国已甘梅尉隐，好官重超木天思。","星邀使节还霄汉，秋老菩提别祖师。","荒寺九旬成底事？","游装初刻难馀诗。"]},{"t":"酬张将子给事","f":"五言律诗","c":["宦况梧垣热，如君冷独殊。","巷稀车马过，门少吏人趋。","奏事须髯戟，追班意气孤。","冰清金给事，寂寞得同无？"]},{"t":"赠姚以式待诏","f":"五言律诗","c":["姚生忠烈后，供奉意全违。","蛮峒家难问，虔州骨未归！","母妻衣信断，亲故荐书稀。","视草聊承乏，何必入禁闱！"]},{"t":"赠禹航姚孟峡","f":"五言律诗","c":["南来皆薄宦，短褐只斯人。","空向蛮烟老，难分岭树春。","刀头真不死，酒兴岂长贫！","落落同门友，方为献纳臣。"]},{"t":"岭南留后入朝纪事","f":"七言律诗","c":["元戎觐阙伟簪缨，召入东班色迥惊。","边吏初知黄屋贵，宫臣还向直庐争。","朝廷有礼宁宜亵，藩镇何知自使轻！","莫怪诸侯多跋扈，此曹驾驭本虚名。"]},{"t":"闻谤","f":"五言律诗","c":["贝锦班行构，谗人计亦愚。","所关伤国体，不为惜孱躯！","志士终难辱，微官岂待驱！","明朝拂衣去，幸谢李金吾。"]},{"t":"临轩曲 其一","f":"七言绝句","c":["从龙初沐圣恩波，诏选词臣辟制科。","格外郎官叨与试，本朝异数恐无多。"]},{"t":"临轩曲 其二","f":"七言绝句","c":["经年廷议许临轩，今日真承圣主恩。","櫜笔晓趋双阙下，恭随胪唱入端门。"]},{"t":"临轩曲 其三","f":"七言绝句","c":["衮衣黄幄殿中间，玉几凭临咫尺攀。","跪迎炉烟宣履历，分明觌面识龙颜。"]},{"t":"临轩曲 其四","f":"七言绝句","c":["面对安详霁圣容，香烟深处闪重瞳。","天心可否无人识，御笔高低点不同。"]},{"t":"临轩曲 其五","f":"七言绝句","c":["唱罢勾胪肃仗齐，小臣分号殿东西。","千官班静相公出，恭请天恩御赐题！"]},{"t":"临轩曲 其六","f":"七言绝句","c":["内外关防视锁闱，金吾传奉凛天威。","书生逻卒寻常见，争似银貂共锦衣。"]},{"t":"临轩曲 其七","f":"七言绝句","c":["内臣黄帕捧书来，香案从容信手开。","遥见阁臣承旨起，御题拟就圣人裁。"]},{"t":"临轩曲 其八","f":"七言绝句","c":["麻纸龙文拂案黄，欲登宸翰费端详。","犹防次第违经传，口诏传宣有巨珰。"]},{"t":"临轩曲 其九","f":"七言绝句","c":["跸声起去晷将斜，老笔难矜旧有花。","日暮大官勤赐膳，传闻辇驾在「文华」。"]},{"t":"临轩曲 其十","f":"七言绝句","c":["词澜正倒夜偏阑，中使频催蜡烛残。","帝辇欲还宫漏促，花砖队队宿鹓鸾。"]},{"t":"临轩曲 其十一","f":"七言绝句","c":["当场洒笔惯惊人，锦玉围观讶有神。","剔烛细书「光武论」，内家也解点头频。"]},{"t":"临轩曲 其十二","f":"七言绝句","c":["分衡早敕玉堂仙，夜半帘前忽放还。","独召阁臣留便殿，堂餐直被禁中传。"]},{"t":"临轩曲 其十三","f":"七言绝句","c":["侍臣收卷上亲临，惭愧么么费圣心。","誊录诸生沾帑赐，同朝争羡主恩深。"]},{"t":"临轩曲 其十四","f":"七言绝句","c":["未央宫阙卷初呈，内殿班齐贺圣明。","面敕言官严检举，当轩拆号御填名。"]},{"t":"临轩曲 其十五","f":"七言绝句","c":["中兴特重玉堂宾，固请加恩放八人。","不是圣朝恩太吝，分明珍惜笼微臣。"]},{"t":"临轩曲 其十六","f":"七言绝句","c":["最怜新进与同升，郡吏、曹郎籍漫凭。","曾荷相公援例请，圣恩特赐一条冰。"]},{"t":"临轩曲 其十七","f":"七言绝句","c":["旷典能无旧例遵，榜头端属首揆抡。","即居卢后犹疑忝。","盛事宁堪第一人！"]},{"t":"临轩曲 其十八","f":"七言绝句","c":["煌煌手诏夜深传，八士同时入木天。","才是国恩难报日，旁人莫漫羡登仙！"]},{"t":"临轩曲 其十九","f":"七言绝句","c":["敕使凌晨候谢恩，口传天语浃春温。","榜中怕有冯唐老，为报青年慰至尊！"]},{"t":"临轩曲 其二十","f":"七言绝句","c":["新恩初许禁中行，为谒先师阁吏迎。","再拜中堂前致谢，共称天子让门生。"]},{"t":"谒谢山阴师，值五十初度，窃睹御赐斐叠，敬呈二首 其一","f":"七言律诗","c":["书生新谒相公尊，再拜中堂故事存。","自诧榜居苏轼列，岂期荐出少师门！","老才入彀惊知遇，庆值悬弧睹圣恩。","闭阁悄然无贺客，数株桃李照庭轩。"]},{"t":"谒谢山阴师，值五十初度，窃睹御赐斐叠，敬呈二首 其二","f":"七言律诗","c":["吾师遇主早登庸，岳降佳辰帝眷浓。","沧海波涛勤捧日，蛮天瘴疠久从龙。","衮衣不受三孤命，铁券坚辞五等封。","才及门墙随上寿，尚方珍赐庆遭逢。"]},{"t":"舟中闻新命有作 其一","f":"七言律诗","c":["新命惊闻邸诏传，遥从鹢首拜垆烟。","朝廷多难叨非分，史馆无人与备员。","报国祗馀垂老笔，成名偏在播迁年。","词林故事咨前辈，此日承恩绝可怜！"]},{"t":"舟中闻新命有作 其二","f":"七言律诗","c":["教习三年典故存，迁除有例相臣援。","读书特荷临轩宠，供职真因视草烦。","吾道艰难羞破格，圣朝浩荡易承恩。","词头久亵丝纶体，珍重王言报至尊。"]},{"t":"梧州杂诗 其一","f":"五言律诗","c":["跋扈南雄将，新年果弃关。","君王御便殿，召对及卑班。","万乘应持重，两宫未敢攀。","独怜彭御史，抗谏动龙颜！"]},{"t":"梧州杂诗 其二","f":"五言律诗","c":["此将昔移镇，吾知弃岭逃。","比肩难节制，饱肉且旌旄！","共有登坛望，宁甘乘障劳！","身先诣吏士，惠国尔功高。"]},{"t":"梧州杂诗 其三","f":"五言律诗","c":["圣驾真难动，人心系去留。","连朝惊羽檄，有诏御龙舟。","禁旅因时宠，纶扉独坐愁。","内家灯火盛，向夕灿中流。"]},{"t":"梧州杂诗 其四","f":"五言律诗","c":["侧耳羊城信，穿烽二使来。","诏开藩镇泣，风斗海船回。","事变知天意，时危有将才。","长城真可恃，驻跸漫惊猜！"]},{"t":"梧州杂诗 其五","f":"五言律诗","c":["将帅加专敕，今晨百道飞。","如何罪己诏，立待吮毫挥！","义动三军愤，功凭一纸微。","颇闻李公子，开读泪沾衣！"]},{"t":"梧州杂诗 其六","f":"五言律诗","c":["遽有苍梧幸，凄凉别小楼。","喜无游宦橐，得上舍人舟。","失伴声相识，饱帆夜未收。","暗中勤借问，车驾在前头。"]},{"t":"梧州杂诗 其七","f":"五言律诗","c":["衰草荒山岸，宵分野烧红。","从官时遇盗，篙楫已论功。","树黑苍梧近，江清漓水通。","同时迎驾者，安定一军雄。"]},{"t":"梧州杂诗 其八","f":"五言律诗","c":["端皇陵寝近，上谒小臣从。","金殿晨开锁，黄衣夜扫烽。","江山迎帝盖，松柏惨天容。","下岭还瞻望，祥云已尽封。"]},{"t":"梧州杂诗 其九","f":"五言律诗","c":["请对真何事，寒蝉此日喧。","露章承内旨，诏狱见君恩。","负国罪应得，除奸功莫论！","虏氛还咫尺，朝局已全翻！"]},{"t":"梧州杂诗 其十","f":"五言律诗","c":["诏狱非仁政，况逢离乱晨。","从龙宽典得，请剑小臣频！","狼狈悲同类，艰危附党人。","山阴真相国，申救跪沙滨。"]},{"t":"梧州杂诗 其十一","f":"五言律诗","c":["桂林留守重，奏使亦频来。","咫尺青骢返，频烦白简催。","廷争犹未息，圣怒已将回。","好是徼恩放，休称苏轼才！"]},{"t":"梧州杂诗 其十二","f":"五言律诗","c":["独树维舟处，联樯并楚伧。","同官应有疏，入狱自伤情！","事定交如旧，天回论渐平。","凄凉金给谏，破舫听人争！"]},{"t":"梧州杂诗 其十三","f":"五言律诗","c":["执政今何日，山阴又闭门！","未须论相业，且莫负君恩！","典故词林重，纶音国体存。","小臣有封事，职在敢无言！"]},{"t":"梧州杂诗 其十四","f":"五言律诗","c":["僻处朝廷小，虚名礼法持。","谁迎郧国至，不救粤东危？","元老盈廷谤，书生一语移。","阙前争论日，大体幸毋亏！"]},{"t":"梧州杂诗 其十五","f":"五言律诗","c":["庙议几时决，滇南使久羁。","请封恩莫惜，矫诏罪何辞！","属国天王凛，朝廷竖子欺。","台中诸御史，肯一问狐狸？"]},{"t":"梧州杂诗 其十六","f":"五言律诗","c":["镇峡关门破，传闻大将跳。","内携诸寨主，乡导各山猺。","楚塞险从失，胡儿马未骄。","休兵图转战，还恃冠军骁！"]},{"t":"梧州杂诗 其十七","f":"五言律诗","c":["粤东频奏捷，骁锐并争先。","丑虏孤城合，蝥弧匹马搴。","定需坚壁垒，切勿恃楼船！","西路援兵下，胡为不肯前？"]},{"t":"梧州杂诗 其十八","f":"五言律诗","c":["两粤嗟新败，朝廷波浪中。","守藩宜有罪，司马且论功。","赏极复何劝？","恩叨岂觉隆！","灰心百战将，封与烂羊同！"]},{"t":"梧州杂诗 其十九","f":"五言律诗","c":["远闻洪少宰，父子丧高州。","守将罪难问，先臣恤岂酬！","久知卑制使，窃恐效诸侯！","近地还如此，輶轩咫尺愁！"]},{"t":"梧州杂诗 其二十","f":"五言律诗","c":["端州兵不下，返旆禦淮侯。","莫问粤东急，须防内地忧。","督师真失策，酿祸至今留。","受诏虚縻饷，何时厌尔求！"]},{"t":"梧州杂诗 其二十一","f":"五言律诗","c":["朝睹南阳奏，强藩已就擒。","弃城知法在，问罪见谋深。","帐外军声寂，怀中帝诏临。","两年三授首，真是快人心！"]},{"t":"梧州杂诗 其二十二","f":"五言律诗","c":["西来吕相国，闻丧独松州。","恋阙情空切，收京志未酬！","天意难将测，不慭老臣留。","寂寞纶扉内，先朝几白头！"]},{"t":"梧州杂诗 其二十三","f":"五言律诗","c":["黔阳书讯至，相忆几经秋。","入蜀吾兄在，筹滇刺史忧！","中伤凭绛灌，外议重钱刘。","节钺危时贱，何心向汝谋！"]},{"t":"梧州杂诗 其二十四","f":"五言律诗","c":["闭门坚请假，吾道欲谁亲！","瘴疠安蛮俗，班行畏蜀人。","迁除乱日窃，功罪几时真！","寄语程司马，饼师泪正新！"]},{"t":"梧州杂诗 其二十五","f":"五言律诗","c":["学士逃荣久，三年不押班。","坚辞李泌相，敢恋谢安山？","蛮峒家初寄，中书诏且颁。","倘徼开史局，予岂望投閒！"]},{"t":"梧州杂诗 其二十六","f":"五言律诗","c":["小舟三伏过，避热苦无方。","远伋馀冰井，虚名愧玉堂！","更愁秋雨毒，颇忆桂林凉。","乞假疏三上，徼恩附野航！"]},{"t":"圣德诗","f":"五言古诗","c":["文帝贵止辇，太宗宝魏徵。","古来神圣主，皆有纳谏名。","我皇仁且孝，不大色与声。","小臣叨侍从，窃睹神采英。","大帅对失措，圣度和且平。","所以诸藩镇，见者识中兴。","给谏触太后，愚直气以盈。","举朝请加诛，受杖罚殊轻。","及与群臣语，往往叹其清。","瞿相老崛强，遇事上书争。","温纶皆手答，曾无勉强情。","去年献史卷，拟同金鉴呈。","今复问主上，还经御览曾？","所言过戆直，左右因相倾。","上言实未读，朕殊有愧卿。","从此事披阅，勿负谆谆诚！","举朝叹圣德，臣等实不能！","虚怀本天授，皇哉我圣明！"]},{"t":"初度日，承袁特丘、金道隐枉诗见赠，用韵奉答","f":"七言律诗","c":["犬马衰辰病里过，双篇忽堕宠施多。","未妨李白权供奉，敢比苏瞻佔制科！","顾我劣输佳句法，悲君生荷圣恩波！","舟中得假堪酬唱，兴罢朝参冷玉呵！"]},{"t":"哭同年杨庶常三首 其一","f":"五言律诗","c":["之子黔阳彦，同门最少年。","主恩伤贾谊，吾道失颜渊！","纱帐频联坐，花砖亦比肩。","修文宁不足，夺我玉堂仙！"]},{"t":"哭同年杨庶常三首 其二","f":"五言律诗","c":["才惊君卧病，易箦即兹辰！","不问维摩疾，谁知原宪贫！","苔痕侵枕席，药物吝同人！","握手床前诀，伤心托老亲！"]},{"t":"哭同年杨庶常三首 其三","f":"五言律诗","c":["八人三散失，尔殁更萧条！","素幔孤灯耿，桐棺万里遥。","名成多难日，死在圣明朝。","身后毋劳念，君恩敢代徼！"]},{"t":"章北院行","f":"七言古诗","c":["昔年避难游云间，章公脱身沔阳还。","人言汹汹匿不得，翻然投躯誓马革。","天子亲征驻湖南，赐公节钺收湖北。","昔何巽懦今何雄，能骑生马挽强弓！","身先士卒亲搏战，身死人称「章北院」！"]},{"t":"郧将军入对歌","f":"七言古诗","c":["将军趋朝求召见，天子传宣御水殿。","将军廷辨声怒嗔，百官拱手颜色变。","中使促对上龙舟，有事面奏香案头。","舟中天子东面坐，将军俯伏汗交流。","汗流浃背猛气沮，诏谓将军从容语。","垆烟移近再三陈，但闻誓死报明主！","叩头再拜出君门，忆起胸中未尽言。","天威咫尺说不得，始信君王是至尊。"]},{"t":"沮封篇","f":"七言古诗","c":["去夏遣使册封滇，贼臣矫诏封使还。","滇人请命求国号，廷议可否将一年。","国号拟上上未允，郧国将军来朝天。","将军入朝沮封议，旧主封者谁敢异！","坐召滇使谒楼船，词严义正色凛然。","自陈己罪「犯京阙」，汝曹徒扰西南偏！","圣恩赦我宁有汝？","与我同心报明主！","本朝异姓无王爵，上违祖制谁敢许！","鞭弭櫜鞬足周旋，汝曹勿欺天子孱！","滇使叩头唯唯退，举朝争叹将军贤！","将军此议真不朽，滇人闻言能信否？","为语使者复命归，勿谓议出廷臣口！"]},{"t":"空船行，为金道隐赋","f":"七言古诗","c":["给谏被逮身萧然，身外长物一空船。","金吾求贿苦不遂，破船估值十千钱。","董生守船陈苦词，此船留裹给谏尸。","姚髯仗剑船头坐，腐儒可笑又可悲！","须臾攘臂牵船去，两生抵死留不住。","金吾移住空船里，有子十龄旋堕水。","伤心卧病未经旬，禳祓无功金吾死！","共惊凶物无人留，空船弃置江东头。","给谏放回沙上卧，送船与渠渠不收！"]},{"t":"哭会稽董孝荩","f":"七言律诗","c":["苍梧瘴疠连朝恶，终日哭人泪未乾！","万里避胡同作客，一时归汉尔无官！","孤舟得病扶持少，蛮郡求医药饵难！","垂死尚祈诗瞑目，诗传泉下益悲酸！"]},{"t":"哭晏云章","f":"七言律诗","c":["春官同舍饶文藻，自入苍梧涕泪频！","蹭蹬昨年垂翅客，伶仃今日白头亲！","哭声万里孤舟夜，墓草千秋五岭春。","海内词坛零落尽，唱酬此后更何人！"]},{"t":"哭董紫?","f":"五言古诗","c":["蛮乡淹瘴疠，闽海共艰难。","皮骨殊方老，神情白昼寒。","辞荣求远使，破格拜天官。","报国时甘忤，思亲泪未乾！","九原留鬓发，万古葬衣冠。","久蓄南还橐，开箱不忍看！"]},{"t":"为金道隐给谏请改戍得允","f":"五言律诗","c":["投荒不可去，为叩九重阍。","远道亡童仆，残躯负杖痕！","罪甘烟戍死，帝念直声存。","雨露真祈得，同朝并荷恩。"]},{"t":"七夕，同彭然石职方集山阴相国舟次","f":"五言律诗","c":["江云暗七夕，官烛伴孤舟。","夜半一杯酒，相公新白头。","方乱难求去，无山可乞休。","座中楚司马，不用苦悲秋！"]},{"t":"得假，同朱御史不敏西上","f":"七言律诗","c":["苦忆虞山秋气清，病中得假许西行。","滩当险处风偏怒，客欲眠时月倍明。","促织连江吟次第，长鱼裂水掷纵横。","泊船喜藉霜威肃，睡著开篷迥不惊。"]},{"t":"中秋夜至桂林，喜晤曼公、鉴在 其一","f":"七言律诗","c":["苦忆朋簪趁客船，恰逢良夜聚樽前。","风尘岂意存吾辈，须鬓休惊异昔年！","蛮地久居秋乍冷，故人相见月偏圆。","乱来此夕皆堪念，震泽、双峰最可怜！"]},{"t":"中秋夜至桂林，喜晤曼公、鉴在 其二","f":"七言律诗","c":["令节扁舟若与期，相逢犹怪客来迟！","绣衣躯干经时伟，学士歌声自昔悲！","老去弟兄惟纵酒，乱中年月已编诗。","龙眠秋色应如奋，今夜何人赋所思？"]},{"t":"留守生日，用诸公韵","f":"七言古诗","c":["阃外平章鬓欲苍，胡床啸咏兴清狂。","起居未肯随蛮俗，风物稍怜近楚乡！","座上称诗同放逐，帐前行酒尽冠裳。","秋成勿使催科扰，愿听农歌一举觞！","幕府清秋兴可怜，开樽召客共筹边。","桂花自劝东皋酒，新月愁含楚塞烟。","人世荣名兼将相，半生出处授神仙。","明年此日知尤健，拟荐江心第一泉！"]},{"t":"龙隐洞九日","f":"七言律诗","c":["司马搜奇汎菊杯，灵岩生面喜重开。","悬崖昨日攀萝上，古道今朝并马来。","勒石勋名空岁月，磨碑党籍长莓苔。","千秋不数龙山宴，幕下谁非作赋才！"]},{"t":"和彭然石西上舟中见怀之作","f":"七言律诗","c":["自别苍梧双眼清，思君待月几回明。","骚坛乱后馀同调，桂棹秋来悔独行！","帷幄伴愁双钓艇，班行侧目两狂生。","词林忝窃真惭汝，佳句深吟倍惨情！"]},{"t":"别山草堂 其一","f":"七言律诗","c":["本朝相业数江陵，奕世重瞻司马兴。","老向沙场浑是胆，閒栖丈室已如僧。","秋风野旷三间屋，静夜篱疏一点灯。","此地赖君留啸咏，肯容胡骑尚飞腾？"]},{"t":"别山草堂 其二","f":"七言律诗","c":["侍郎别业敞江汀，剃草编篱带七星。","醉倚巴童挥露布，时留楚客续骚经。","灯前新鬓军中白，槛外诸峰雨后青。","但设琴尊君自去，柴门松竹不须扃。"]},{"t":"漓江泛舟行，为杨武陵赋","f":"七言古诗","c":["桂林好客武陵侯，邀我九月虞山游。","虞山酒罢月初出，乘月还泛漓江舟。","水清沙白石磊磊，小艇一双放上流。","酒船坐客歌船并，隔船小伎司酒筹。","丝管啁啾鼓吹乱，忽然声绝扬清讴。","是时天气方高秋，四山苍苍烟雾收。","中流放棹船不动，听曲大鱼低昂浮。","曲终月皎四方静，更鼓声声城上楼。","城上人语不敢睡，城门不锁彻夜留。","城边怪石如人立，醉中认是侯家驺。","侯家劝客樽如卣，夜深客醉劝不休。","主人一饮尽数斗，坐客何人堪献酬！","送客归去月更好，洗杯对月回船头。","我时醉卧还侧耳，笙歌水上去悠悠。"]},{"t":"虞山歌，为留守相公赋","f":"七言古诗","c":["虞山苍苍日初薄，松风江水涛声合。","我乘清秋拜舜祠，丹青玉殿何寂寞！","自从中国污腥膻，冠裳委地纷可怜。","群后、二妃有何幸，冕旒环佩妆俨然！","问此半壁为谁有？","烽大曾经百战后。","焦侯、周帅再全城，论功指纵归留守。","留守坐啸不临戎，从容袖手驱群雄。","两雄忘躯为谁战，感公忠义成公功。","公于此山有天意，南来早授神仙记。","授公诸记函尽开，吉凶一一分明示。","以兹听运意常閒，许公今岁锦衣还。","还时却别此山去，更入吴中寻旧山。","吴山名与粤山共，粤为虞帝吴为仲。","公功在粤家在吴，两地山皆以公重。","山川宾客藉公传，铭公应在虞山巅。","梯升学士如椽笔，并纪同游高会年。"]},{"t":"桂林杂诗 其一","f":"五言律诗","c":["桂林朱邸旧，桐叶国初封。","恩赐亲王礼，宫依独秀峰。","朝趋沾酒醴，服御暗蛟龙。","府内萧条甚，何心泣庶宗！"]},{"t":"桂林杂诗 其二","f":"五言律诗","c":["虞帝南巡处，到今祠庙荒。","冕旒群后肃，环佩二妃锵。","薄暮尧山紫，临江楚树苍。","松声泛仙乐，疑在洞庭傍。"]},{"t":"桂林杂诗 其三","f":"五言律诗","c":["洞壑琳宫壮，土人祠伏波。","澄潭舣舟楫，虚阁会笙歌。","铜柱铭犹灿，云台画孰多？","来游诸将帅，此志勿蹉跎！"]},{"t":"桂林杂诗 其四","f":"五言律诗","c":["滇帅声名久，今知爵太尊。","流星边檄至，卜日上公婚。","真作室家计，愁伤部曲恩。","稍闻胡卫国，匹马备关门。"]},{"t":"桂林杂诗 其五","f":"五言律诗","c":["好客瞿丞相，蛮方秋兴高。","为怜双桂树，新筑「小东皋」。","家伎寻常出，诗篇倡和豪。","此生经授记，不用更焦劳。"]},{"t":"桂林杂诗 其六","f":"五言律诗","c":["张髯玉堂客，报国老戎衣。","久办沙场死，还能马上飞。","书生喜见敌，老将让临机。","坚卧榕江上，师旋独不归。"]},{"t":"桂林杂诗 其七","f":"五言律诗","c":["湖南江御史，卧疾伏波门。","久客中湘幕，深衔国士恩。","叙劳官不受，破虏檄犹存。","问著长沙败，伤心指箭痕！"]},{"t":"桂林杂诗 其八","f":"五言律诗","c":["撤防久不进，狡计定如何！","铁骑严关转，奇功鄂国多。","肘应掣瓜里，胆故落麻河。","公论中兴业，终归马伏波。"]},{"t":"桂林杂诗 其九","f":"五言律诗","c":["严城容逐客，旅泊亦艰危。","留守时分韵，将军正画眉。","坐看山色好，浪作楚囚悲！","断酒兼烧砚，丁宁跛阿师！"]},{"t":"桂林杂诗 其十","f":"五言律诗","c":["清绝桂林郡，偏宜北客居。","病苏秋冷日，气爽瘴消初。","也恋朋樽好，深忧将帅疏。","伏波山下棹，稳泊意何如？"]},{"t":"曼公娶妾得同乡女，戏赠","f":"五言律诗","c":["谁意桐溪女，系绳来百蛮。","绸缪会土语，飘泊有烟鬟。","薄命江湖上，新妆吴、楚间。","蛾眉知不妒，应喜见家山！"]},{"t":"昭江寿曼公四十 其一","f":"七言律诗","c":["历岁逃荣守钓矶，可怜初度意多违！","阁麻屡降中书诏，宫锦犹披学士衣。","报国身依丹极老，思亲泪逐白云飞！","兴朝大政需公出，早办收京并马归！"]},{"t":"昭江寿曼公四十 其二","f":"七言律诗","c":["年纪参差雁字斜，同时须鬓老天涯。","围棋共许饶安石，披衮行看迈仲华。","夜洗砚山聊作活，昼乘钓艇且为家。","主恩十召君应起，莫恋沧江负白麻！"]},{"t":"同曼公、树本入仙回洞访严伯玉","f":"五言律诗","c":["窈窕仙源路，崎岖秋雨馀。","喷泉崩古栈，绝岭挂蓝舆。","客是严陵裔，窗存宛委书。","屯军与杂处，可得遂安居？"]},{"t":"到梧州界，闻乱道梗","f":"五言律诗","c":["咫尺梧州路，孤臣去住愁。","烽烟迷日暮，旗帜塞江流。","扈从纷相失，乘舆何处求？","惊闻鲁司马，无故自焚舟！"]},{"t":"送瞿寿明奔难桂林","f":"五言律诗","c":["信是粤西破，元公岂望生。","慈孙哀毁日，小妇别离情！","匍匐宵奔难，风尘哭送行。","平生师友谊，尽在桂林城。"]},{"t":"辛卯元旦","f":"五言律诗","c":["失路逢元日，客心天外孤。","明霞瞻帝座，野服拜香炉。","梧郡城空弃，浔江路罢趋。","同时诸扈从，何处正嵩呼！"]},{"t":"昭江三首 其一","f":"七言绝句","c":["光禄无家寄一舟，香炉茗碗坐江头。","沈沙不是骑鲸去，好共湘累结伴游！"]},{"t":"昭江三首 其二","f":"七言绝句","c":["艰辛海外远趋庭，咫尺音容痛未聆。","匍匐祗拚收骨去，却衔哀恨滞幽囹！"]},{"t":"昭江三首 其三","f":"七言绝句","c":["失路孤臣何处奔，仙回洞里故人存。","孙嵩复壁谁分义，榜掠甘心誓不言。"]},{"t":"哭留守公四章 其一","f":"七言律诗","c":["桂林陷后屡登陴，此日孤城岂更支！","坐啸但凭天意稳，痴忠不信粤疆危！","也知滇帅空邀饷，却恨焦侯远驻师！","闻有七人同日死，张髯以外定为谁！"]},{"t":"哭留守公四章 其二","f":"七言律诗","c":["林生夜梦巨舟沈，独有吴郎水未侵。","幕下几人能脱网，危时早计岂成擒！","可怜供帐盘餐却，犹许累囚唱和吟。","司马奋髯公击节，从容激烈两同心。"]},{"t":"哭留守公四章 其三","f":"七言律诗","c":["仙翁授记有玄机，为说扶公返旧扉。","共信锦衣思结伴，讵知马革是「荣归」！","慈孙收血奔难到，爱子趋庭志已违！","传说吴江杨义士，窃携骸骨出重围。"]},{"t":"哭留守公四章 其四","f":"七言律诗","c":["天隅文物仗公存，多士从龙半在门。","疏拙无因频荷荐，圣明不用亦衔恩。","特乘休沐趋戎慕，为献新诗赏直言。","回忆虞山高宴夜，桂华明月最伤魂！"]},{"t":"哭张司马四首 其一","f":"七言律诗","c":["负郭秋灯聚草堂，江头送别色凄凉。","申胥复楚功难就，张悌捐躯志竟偿！","报国正宜留热血，完名何苦殉危疆？","天涯屈指奇男子，忆尔雄姿泪几行！"]},{"t":"哭张司马四首 其二","f":"七言律诗","c":["下笔真惊倚马奇，逢君酒后兴何悲！","雄文不草收京檄，绝命空传骂贼诗！","七日忍饥还唱和，九原有伴足追随。","樽前怪尔须髯戟，长似睢阳嚼齿时。"]},{"t":"哭张司马四首 其三","f":"七言律诗","c":["榕江大帅已全奔，坚卧要谁驻壁门。","好养健儿曾吮血，更无弱息与招魂！","老妻浅土何人葬？","遗稿烽中几册存！","敢信江陵遂不祀，荆州或有相公孙！"]},{"t":"哭张司马四首 其四","f":"七言律诗","c":["并马江头向碧岑，星岩龙隐日追寻。","看君摇笔须眉动，把我新诗泣涕吟。","难后尚随门下吏，箧中长宝故人簪。","同人属和张、瞿韵，几度拈来痛不任！"]},{"t":"浔州帅","f":"七言古诗","c":["夙昔不齿浔州帅，冒封大国殊可愧！","跋扈抗命诸镇无，阴谋矫诏中朝祟。","龙舟仓卒向西巡，放兵大掠左江滨。","百官扈从纷相失，道路梗塞困小臣。","焦侯平乐城不守，单骑追驾向南走。","祗闻假道上乌蛮，何意投躯喂虎口！","浔帅乞降苦无由，要侯请解昔日仇。","杯酒未终侯遇害，遣儿来献焦侯头！"]},{"t":"过羊城纪事","f":"五言律诗","c":["不信粤东破，坚城岂望援！","捷书方狎至，残骑欲宵奔。","振旅全浮海，空营始献门。","西关输款将，遗恨范承恩。"]},{"t":"虔州有怀","f":"古风","c":["月映荒城夜泊舟，昔贤义气此中休。","曾惊?篥罗毡帐，忽见嵯峨笑虎头。","胡运未终江右败，将星初堕岭南忧。","楼船官舍衔杯处，回首天涯忆二刘！"]},{"t":"上天堂山访隐，主人不顾，作诗而去","f":"七言律诗","c":["出关何意再还闽，拟向千峰老此身。","幸有香台堪遁世，况多道伴可成邻！","岭云自去谁留客，巢鹤惊飞亦避人。","吾道既非应共弃，莫疑物态有疏亲！"]},{"t":"哭峡江曾二云老师 其一","f":"七言律诗","c":["凶问初传暗里惊，闽关趼足为谁行？","踏穿岭表三山近，望到天隅一柱倾！","沧海未能容信国，白头毕竟丧真卿！","同时义士吞声泣，不为门墙独惨情！"]},{"t":"哭峡江曾二云老师 其二","f":"七言律诗","c":["冰蘖清风海内望，至今遗爱泣闽乡。","身栖绝岛思存宋，梦入先朝只辅唐。","闾里自来臣节著，家门都为国恩亡。","相随犹有雏孙在，此日巢倾若与藏！"]},{"t":"哭峡江曾二云老师 其三","f":"七言律诗","c":["有客乘风自厦门，灵光孤殿岿然存。","阃权海上尊元老，封事天南动至尊。","蜡诏未叨明主赐，麻纶犹出上皇恩。","新衔鹊印随颁给，曾慰孤臣万里心。"]},{"t":"哭峡江曾二云老师 其四","f":"七言律诗","c":["昔岁谬叨漳浦荐，主恩特诏试天官。","书生不以先容进，国士偏承破格看。","一命滥参延郡幕，三年窃戴侍臣冠。","同时知己捐躯尽，每念师恩泪未乾！"]},{"t":"曼公书至，得山阴师死事信 其一","f":"七言律诗","c":["去岁风闻疑至今，客来果说大星沈。","青天已毕蠲躯志，白日空悬报主心！","多难相依臣节苦，异时不去国恩深。","中兴未奏公先死，泪洒天南听捷音！"]},{"t":"曼公书至，得山阴师死事信 其二","f":"七言律诗","c":["共羡吾师遇主知，五年车驾镇相随。","边书忽到催朝急，密旨偏承下直迟。","血碧人间千载恨，柱摧天外九重悲。","乘舆此日蛮荒外，左右颠危更仗谁！"]},{"t":"曼公书至，得山阴师死事信 其三","f":"七言律诗","c":["曾为三策筹滇事，纶阁传看亦动容。","庭议只知争祖制，帝心原自慎藩封。","图纾国难身先殒，为荷君恩祸独钟！","门下夕郎同日死，九原含笑得相从。"]},{"t":"曼公书至，得山阴师死事信 其四","f":"七言律诗","c":["制科忝出陆公门，同是门生独荷恩。","规讽每蒙倾耳听，询谋偏许纵情论。","受知不浅常跻阁，相见无时特谕阍。","何事违师苦求去，祗今西望漫伤魂！"]},{"t":"行路难 其一","f":"七言绝句","c":["望见梧云路不通，西来贯甲引弓雄。","邻船烧尽榜人窜，独树孤舟系晚风。"]},{"t":"行路难 其二","f":"七言绝句","c":["夜黑山深暴雨催，虎狼队里脱身来。","孝廉认得同行伴，映竹茅斋为我开。"]},{"t":"行路难 其三","f":"七言绝句","c":["竹屋初糊未稳眠，山猺窃发又纷然。","滩头便是焚舟处，仍杂村氓上渡船。"]},{"t":"行路难 其四","f":"七言绝句","c":["斗柄横参冬已残，蛮方天气不知寒。","梅花一树牛栏外，每日扶藜两度看。"]},{"t":"行路难 其五","f":"七言绝句","c":["谁传邸诏到山扃，信是乘舆驻朗宁。","愁绝浔州江路断，致身那得奋飞翎！"]},{"t":"行路难 其六","f":"七言绝句","c":["穷山雨闭吏人呼，缯缴漫漫何处逋？","几度被兵装已尽，倾家急难是苍梧！"]},{"t":"行路难 其七","f":"七言绝句","c":["经旬守渡坐江头，典尽春衣问小舟。","偏遇买粮船正过，弯弓停楫在中流。"]},{"t":"行路难 其八","f":"七言绝句","c":["多难逢君事已迟，偷生到此岂宜悲！","可怜身外无长物，留取孤臣一卷诗！"]},{"t":"行路难 其九","f":"七言绝句","c":["憔悴累囚生意微，思归应是梦中归。","山头却望摩空鸟，那得凌风学尔飞！"]},{"t":"行路难 其十","f":"七言绝句","c":["孤儿相失已三年，万死蛮烟觅汝还。","日夕牵衣今又散，乱山何处哭苍天！"]},{"t":"行路难 其十一","f":"七言绝句","c":["日落孤村数已穷，摩刀相向忽开笼。","草间一夜成甘寝，病骨何曾解怕风。"]},{"t":"行路难 其十二","f":"七言绝句","c":["近关怕见北军装，掩面叉胸避道旁。","忽说姓名惊改色，声音认得是同乡。"]},{"t":"行路难 其十三","f":"七言绝句","c":["十日无栖此夜偏，故人布被拟同眠。","那知难后贫如我，抵足牛衣剧可怜！"]},{"t":"行路难 其十四","f":"七言绝句","c":["乞假辞朝去未回，伤心囚服此时来！","龙舟驻处江声急，辇路荒残马矢堆。"]},{"t":"行路难 其十五","f":"七言绝句","c":["五更起坐自温经，还似书声静夜听。","梵唱自矜能仿佛，老僧本色是优伶。"]},{"t":"行路难 其十六","f":"七言绝句","c":["刺史乡情荷已多，艰危无奈故人何！","才从虎穴全巢卵，又送穷鱼脱网罗。"]},{"t":"行路难 其十七","f":"七言绝句","c":["寄语西村老布袍，旧时笥箧等閒抛。","新诗一字浑忘却，壁上留题为我抄！"]},{"t":"行路难 其十八","f":"七言绝句","c":["赤脚敲门是再生，痴儿留得故人情。","邻妪辍泣来相废，笑指今晨有哭声！"]},{"t":"行路难 其十九","f":"七言绝句","c":["惭负当年博奥声，车裘已尽听君行。","三更病渴思涓滴，错唤獠奴阿段名。"]},{"t":"行路难 其二十","f":"七言绝句","c":["望见星岩泪已潸，稽呵有吏认愁颜。","端州太守曾相识，一字包羞许过关。"]},{"t":"行路难 其二十一","f":"七言绝句","c":["郡阁相邀揖罢还，传心御幄敢跻攀。","使君莫怪频流涕，原是螭头旧侍班。"]},{"t":"行路难 其二十二","f":"七言绝句","c":["阛阓烧残遍垝垣，徘徊难觅旧居门。","老兵病卧前相问，为指孤吟阁尚存。"]},{"t":"行路难 其二十三","f":"七言绝句","c":["吾乡幕客老天隅，为拟东还结伴趋。","难后赤身行不得，重怜觅渡向苍梧！"]},{"t":"行路难 其二十四","f":"七言绝句","c":["转眼佣奴便作威，解骖属望故人非。","同乡好友输金足，惭愧全家尽赎归！"]},{"t":"行路难 其二十五","f":"七言绝句","c":["好事潘生剧可怜，从龙身丧左江边！","僮奴掠卖胡军里，说著低声泪点悬！"]},{"t":"行路难 其二十六","f":"七言绝句","c":["难后同年尚几存，惠州高蹈早为髡。","闭门野史犹堪葺，莫负临轩特典恩！"]},{"t":"行路难 其二十七","f":"七言绝句","c":["连朝水长过山腰，村市填波波怒号。","估客一时牵缆去，榜人呼我共撑篙。"]},{"t":"行路难 其二十八","f":"七言绝句","c":["准拟龙车尔定随，那期雁字又参差。","老兄愿让「生还集」，乞与同门标近诗。"]},{"t":"行路难 其二十九","f":"七言绝句","c":["维舟崖寺试追攀，却说飞来自皖山。","乡国十年归未得，暂留此地算生还。"]},{"t":"行路难 其三十","f":"七言绝句","c":["城上钟鸣作吼声，旧传此物是龙精。","城亡一夜摩空去，不与人间报五更。"]},{"t":"行路难 其三十一","f":"七言绝句","c":["寄语茅坪跛阿师，故人过岭也披缁。","追寻万里门生谊，莫老蛮方负所思！"]},{"t":"行路难 其三十二","f":"七言绝句","c":["双脚蹒跚卧路陲，客来相慰漫兴悲！","乘舆何处吾归去，可是高车驷马时？"]},{"t":"行路难 其三十三","f":"七言绝句","c":["严城背日客心哀，往事凄凉对劫灰。","江右、岭南千古恨，不堪回首郁孤台！"]},{"t":"行路难 其三十四","f":"七言绝句","c":["逆旅逢亲意转迷，无家归去傍人栖。","出门斜指芦帘内，说是同乡别驾妻。"]},{"t":"行路难 其三十五","f":"七言绝句","c":["寄去家书到未曾，烦君口信字难凭！","故园兄弟休痴望，头白归来是老僧。"]},{"t":"行路难 其三十六","f":"七言绝句","c":["江村初夏树阴阴，望去禾新客途深。","跋涉最怜孺子苦，麻鞋破脚暗伤心！"]},{"t":"行路难 其三十七","f":"七言绝句","c":["刚是行年四十来，不堪人事首重回！","只今出世毋嫌晚，便算兹辰降母胎。"]},{"t":"行路难 其三十八","f":"七言绝句","c":["江村竞渡鼓声新，卧病惊闻初度辰。","莫道五丝难续命，看予几度再生身！"]},{"t":"行路难 其三十九","f":"七言绝句","c":["三年习气已消磨，曾约东还此再过。","古寺烧残老僧死，留予一顶教谁摩？"]},{"t":"行路难 其四十","f":"七言绝句","c":["急水回舟认此村，两株榕树覆山门。","诗笺壁上张如旧，犹带伤秋泪点存！"]},{"t":"行路难 其四十一","f":"七言绝句","c":["铁屩磨穿海上来，仙师有约到蓬莱。","黑风一夜三山失，却望沧波痛哭回！"]},{"t":"行路难 其四十二","f":"七言绝句","c":["移居深巷叩柴荆，问姓开门半日惊。","更说与君惊绝事，痴儿寻得已随行。"]},{"t":"行路难 其四十三","f":"七言绝句","c":["此地招寻独有君，惊看须鬓雪纷纷。","姓名祗许孙嵩识，莫遗通村父老闻！"]},{"t":"行路难 其四十四","f":"七言绝句","c":["自逃方外久忘机，特访名山入翠微。","谷鸟相猜有何意，避人穿过隔溪飞？"]},{"t":"行路难 其四十五","f":"七言绝句","c":["萧寺炊烟渐欲无，僧堂粥饭敢嫌粗！","苦瓜未熟米、盐绝，吃尽山头雨后菇。"]},{"t":"行路难 其四十六","f":"七言绝句","c":["天堂山上人来稀，天堂山僧去不归。","归时托钵予亦去，回听钟声隔翠微。"]},{"t":"行路难 其四十七","f":"七言绝句","c":["扶筇晓上最高峰，岚海平铺四面同。","此际下方人未醒，茫茫都在白云中。"]},{"t":"行路难 其四十八","f":"七言绝句","c":["峚峰关主本同乡，禅寂多年不下床。","为指蒲团相对坐，沙弥初点一枝香。"]},{"t":"行路难 其四十九","f":"七言绝句","c":["头白山僧旧说名，早年持律晚尤精。","客来旋摘新锄菜，打水亲烧折脚铛。"]},{"t":"行路难 其五十","f":"七言绝句","c":["吾师托钵事终南，死后依然守一龛。","说著钳锥随堕泪，旁人不信是同参。"]},{"t":"行路难 其五十一","f":"七言绝句","c":["老僧多病苦修偏，课诵行禅夜不眠。","更荷慈悲留过客，为怜单被自装绵。"]},{"t":"行路难 其五十二","f":"七言绝句","c":["死关侍者老千峰，苦行年深有病容。","见我橐中衣未制，亲携刀尺与裁缝。"]},{"t":"行路难 其五十三","f":"七言绝句","c":["此生已信付寒灰，物外惊疑何处来？","自是禅心死未尽，尚留俗相与人猜。"]},{"t":"行路难 其五十四","f":"七言绝句","c":["望去山腰一缕烟，到来钟梵肃诸天。","道人已习头陀行，为乞蓑衣与种田。"]},{"t":"行路难 其五十五","f":"七言绝句","c":["朝搥钟磬礼袈裟，惭愧男儿始出家！","胡跪阶前求剃草，可能选佛似丹霞？"]},{"t":"行路难 其五十六","f":"七言绝句","c":["招寻有伴入松关，我自栖山尔自还。","别后望云无过念，团瓢只在数峰间。"]},{"t":"行路难 其五十七","f":"七言绝句","c":["自是多生风障深，才抛稚子又关心。","出山送尔寻舟去，指与江头枫树林。"]},{"t":"行路难 其五十八","f":"七言绝句","c":["自别松关苦溯流，更堪烟雨滞孤舟。","竹房无限萧疏兴，来作篷窗万种愁！"]},{"t":"行路难 其五十九","f":"七言绝句","c":["祇园劫后再来兴，耿耿犹存塔院灯。","三市绕完无认得，出门唯识饭头僧。"]},{"t":"行路难 其六十","f":"七言绝句","c":["为指芒鞋更向前，匡庐深处许安禅？","前身应是山居客，说著峰头意惘然！"]},{"t":"行路难 其六十一","f":"七言绝句","c":["头白浔阳老楫师，江村邻舍半相知。","故园桂树闻名久，可识如今剩几枝？"]},{"t":"行路难 其六十二","f":"七言绝句","c":["放棹中流恨短篷，江山如旧恨无穷！","邻船不识伤心事，打鼓鸣锣赛晚风。"]},{"t":"行路难 其六十三","f":"七言绝句","c":["为指孤松问路行，到门应是举家惊！","明晨便逐东风去，屋里平安寄一声！"]},{"t":"行路难 其六十四","f":"七言绝句","c":["惊喜吴江旅榇还，岂期儿女镜团圆！","伤心更有鸰原痛，那得忘情竟放船！"]}]};